    ValueNotifier<String>('Available');
List<Map<String, dynamic>> bookedAppointments = [];

final FlutterLocalNotificationsPlugin
    flutterLocalNotificationsPlugin =
    FlutterLocalNotificationsPlugin();
    
    Future<void> showEmergencyNotification() async {
  const AndroidNotificationDetails androidDetails =
      AndroidNotificationDetails(
    'emergency_channel',
    'Emergency Alerts',
    channelDescription:
        'Notifications for incoming patient emergency requests',
    importance: Importance.max,
    priority: Priority.high,
    playSound: true,
  );

  const NotificationDetails notificationDetails =
      NotificationDetails(
    android: androidDetails,
  );

  await flutterLocalNotificationsPlugin.show(
    1001,
    '🚨 New Emergency Request',
    'A patient has requested emergency assistance.',
    notificationDetails,
  );
}

