'Your symptoms may indicate a medical emergency. Immediate emergency assistance is recommended.': {
  'en_IN': 'Your symptoms may indicate a medical emergency. Immediate emergency assistance is recommended.',
  'hi_IN': 'आपके लक्षण चिकित्सीय आपातकाल का संकेत दे सकते हैं। तुरंत आपातकालीन सहायता लेने की सलाह दी जाती है।',
  'kn_IN': 'ನಿಮ್ಮ ರೋಗಲಕ್ಷಣಗಳು ವೈದ್ಯಕೀಯ ತುರ್ತು ಪರಿಸ್ಥಿತಿಯನ್ನು ಸೂಚಿಸಬಹುದು. ತಕ್ಷಣ ತುರ್ತು ವೈದ್ಯಕೀಯ ಸಹಾಯ ಪಡೆಯಲು ಶಿಫಾರಸು ಮಾಡಲಾಗಿದೆ.',
  'ta_IN': 'உங்கள் அறிகுறிகள் மருத்துவ அவசரநிலையைக் குறிக்கலாம். உடனடியாக அவசர மருத்துவ உதவியைப் பெற பரிந்துரைக்கப்படுகிறது.',
  'te_IN': 'మీ లక్షణాలు వైద్య అత్యవసర పరిస్థితిని సూచించవచ్చు. వెంటనే అత్యవసర వైద్య సహాయం పొందాలని సిఫార్సు చేయబడింది.',
  'ml_IN': 'നിങ്ങളുടെ ലക്ഷണങ്ങൾ ഒരു മെഡിക്കൽ അടിയന്തരാവസ്ഥയെ സൂചിപ്പിക്കാം. ഉടൻ അടിയന്തര വൈദ്യസഹായം തേടാൻ ശുപാർശ ചെയ്യുന്നു.',
  'mr_IN': 'तुमची लक्षणे वैद्यकीय आणीबाणीचे संकेत देऊ शकतात. त्वरित आपत्कालीन वैद्यकीय मदत घेण्याची शिफारस केली जाते.',
  'bn_IN': 'আপনার উপসর্গগুলি একটি চিকিৎসা জরুরি অবস্থার ইঙ্গিত দিতে পারে। অবিলম্বে জরুরি চিকিৎসা সহায়তা নেওয়ার পরামর্শ দেওয়া হচ্ছে.',
},

'Your symptoms appear suitable for basic first-aid guidance. Follow the recommended steps and monitor your condition.': {
  'en_IN': 'Your symptoms appear suitable for basic first-aid guidance. Follow the recommended steps and monitor your condition.',
  'hi_IN': 'आपके लक्षण बुनियादी प्राथमिक उपचार के लिए उपयुक्त लगते हैं। सुझाए गए चरणों का पालन करें और अपनी स्थिति पर नज़र रखें।',
  'kn_IN': 'ನಿಮ್ಮ ರೋಗಲಕ್ಷಣಗಳು ಮೂಲ ಪ್ರಥಮ ಚಿಕಿತ್ಸಾ ಮಾರ್ಗದರ್ಶನಕ್ಕೆ ಸೂಕ್ತವಾಗಿವೆ. ಶಿಫಾರಸು ಮಾಡಿದ ಕ್ರಮಗಳನ್ನು ಅನುಸರಿಸಿ ಮತ್ತು ನಿಮ್ಮ ಸ್ಥಿತಿಯನ್ನು ಗಮನಿಸಿ.',
  'ta_IN': 'உங்கள் அறிகுறிகள் அடிப்படை முதலுதவி வழிகாட்டுதலுக்கு ஏற்றதாகத் தெரிகிறது. பரிந்துரைக்கப்பட்ட வழிமுறைகளைப் பின்பற்றி உங்கள் நிலையை கண்காணிக்கவும்.',
  'te_IN': 'మీ లక్షణాలు ప్రాథమిక ప్రథమ చికిత్స మార్గదర్శకానికి అనుకూలంగా కనిపిస్తున్నాయి. సిఫార్సు చేసిన చర్యలను అనుసరించి మీ పరిస్థితిని గమనించండి.',
  'ml_IN': 'നിങ്ങളുടെ ലക്ഷണങ്ങൾ അടിസ്ഥാന പ്രഥമ ശുശ്രൂഷാ മാർഗ്ഗനിർദ്ദേശത്തിന് അനുയോജ്യമാണെന്ന് തോന്നുന്നു. ശുപാർശ ചെയ്ത നടപടികൾ പിന്തുടർന്ന് നിങ്ങളുടെ അവസ്ഥ നിരീക്ഷിക്കുക.',
  'mr_IN': 'तुमची लक्षणे प्राथमिक उपचाराच्या मार्गदर्शनासाठी योग्य दिसत आहेत. शिफारस केलेल्या पायऱ्या पाळा आणि तुमच्या स्थितीवर लक्ष ठेवा.',
  'bn_IN': 'আপনার উপসর্গগুলি প্রাথমিক চিকিৎসার নির্দেশনার জন্য উপযুক্ত বলে মনে হচ্ছে। প্রস্তাবিত পদক্ষেপগুলি অনুসরণ করুন এবং আপনার অবস্থার উপর নজর রাখুন.',
},

'Your symptoms may require assessment by a healthcare professional. Consider booking a consultation.': {
  'en_IN': 'Your symptoms may require assessment by a healthcare professional. Consider booking a consultation.',
  'hi_IN': 'आपके लक्षणों का स्वास्थ्य पेशेवर द्वारा मूल्यांकन आवश्यक हो सकता है। परामर्श के लिए अपॉइंटमेंट लेने पर विचार करें।',
  'kn_IN': 'ನಿಮ್ಮ ರೋಗಲಕ್ಷಣಗಳಿಗೆ ಆರೋಗ್ಯ ವೃತ್ತಿಪರರ ಮೌಲ್ಯಮಾಪನ ಅಗತ್ಯವಾಗಬಹುದು. ಸಮಾಲೋಚನೆಗಾಗಿ ಅಪಾಯಿಂಟ್‌ಮೆಂಟ್ ಬುಕ್ ಮಾಡುವುದನ್ನು ಪರಿಗಣಿಸಿ.',
  'ta_IN': 'உங்கள் அறிகுறிகளுக்கு ஒரு சுகாதார நிபுணரின் மதிப்பீடு தேவைப்படலாம். மருத்துவ ஆலோசனைக்கு முன்பதிவு செய்வதை பரிசீலிக்கவும்.',
  'te_IN': 'మీ లక్షణాలకు ఆరోగ్య నిపుణుడి అంచనా అవసరం కావచ్చు. సంప్రదింపును బుక్ చేసుకోవడాన్ని పరిగణించండి.',
  'ml_IN': 'നിങ്ങളുടെ ലക്ഷണങ്ങൾക്ക് ഒരു ആരോഗ്യ വിദഗ്ധന്റെ വിലയിരുത്തൽ ആവശ്യമായി വരാം. ഒരു കൺസൾട്ടേഷൻ ബുക്ക് ചെയ്യുന്നത് പരിഗണിക്കുക.',
  'mr_IN': 'तुमच्या लक्षणांचे आरोग्यसेवा व्यावसायिकांकडून मूल्यांकन आवश्यक असू शकते. वैद्यकीय सल्ल्यासाठी अपॉइंटमेंट घेण्याचा विचार करा.',
  'bn_IN': 'আপনার উপসর্গগুলির জন্য একজন স্বাস্থ্যসেবা পেশাদারের মূল্যায়নের প্রয়োজন হতে পারে। পরামর্শের জন্য অ্যাপয়েন্টমেন্ট বুক করার কথা বিবেচনা করুন.',
},
