'SOS will be activated and your location will be shared with emergency medical responders.': {
  'en_IN': 'SOS will be activated and your location will be shared with emergency medical responders.',
  'hi_IN': 'SOS सक्रिय किया जाएगा और आपका स्थान आपातकालीन चिकित्सा सहायता कर्मियों के साथ साझा किया जाएगा।',
  'kn_IN': 'SOS ಅನ್ನು ಸಕ್ರಿಯಗೊಳಿಸಲಾಗುತ್ತದೆ ಮತ್ತು ನಿಮ್ಮ ಸ್ಥಳವನ್ನು ತುರ್ತು ವೈದ್ಯಕೀಯ ಸಹಾಯಕರೊಂದಿಗೆ ಹಂಚಿಕೊಳ್ಳಲಾಗುತ್ತದೆ.',
  'ta_IN': 'SOS செயல்படுத்தப்பட்டு, உங்கள் இருப்பிடம் அவசர மருத்துவ உதவியாளர்களுடன் பகிரப்படும்.',
  'te_IN': 'SOS సక్రియం చేయబడుతుంది మరియు మీ స్థానాన్ని అత్యవసర వైద్య సహాయకులతో పంచుకుంటారు.',
  'ml_IN': 'SOS സജീവമാക്കുകയും നിങ്ങളുടെ ലൊക്കേഷൻ അടിയന്തര മെഡിക്കൽ സഹായികളുമായി പങ്കിടുകയും ചെയ്യും.',
  'mr_IN': 'SOS सक्रिय केले जाईल आणि तुमचे स्थान आपत्कालीन वैद्यकीय मदतनीसांसोबत शेअर केले जाईल.',
  'bn_IN': 'SOS সক্রিয় করা হবে এবং আপনার অবস্থান জরুরি চিকিৎসা সহায়তাকারীদের সাথে শেয়ার করা হবে.',
},
'Emergency assistance will be requested and your location will be shared with medical responders.':
    {
  'en_IN': 'Emergency assistance will be requested and your location will be shared with medical responders.',
  'hi_IN': 'आपातकालीन सहायता का अनुरोध किया जाएगा और आपका स्थान चिकित्सा सहायता कर्मियों के साथ साझा किया जाएगा।',
  'kn_IN': 'ತುರ್ತು ಸಹಾಯವನ್ನು ಕೋರಲಾಗುತ್ತದೆ ಮತ್ತು ನಿಮ್ಮ ಸ್ಥಳವನ್ನು ವೈದ್ಯಕೀಯ ಸಹಾಯ ಸಿಬ್ಬಂದಿಯೊಂದಿಗೆ ಹಂಚಿಕೊಳ್ಳಲಾಗುತ್ತದೆ.',
  'ta_IN': 'அவசர உதவி கோரப்படும் மற்றும் உங்கள் இருப்பிடம் மருத்துவ உதவி பணியாளர்களுடன் பகிரப்படும்.',
  'te_IN': 'అత్యవసర సహాయం అభ్యర్థించబడుతుంది మరియు మీ స్థానాన్ని వైద్య సహాయక సిబ్బందితో పంచుకుంటాము.',
  'ml_IN': 'അടിയന്തര സഹായം അഭ്യർത്ഥിക്കുകയും നിങ്ങളുടെ സ്ഥലം മെഡിക്കൽ സഹായ പ്രവർത്തകരുമായി പങ്കിടുകയും ചെയ്യും.',
  'mr_IN': 'आपत्कालीन मदतीची विनंती केली जाईल आणि तुमचे स्थान वैद्यकीय मदत कर्मचाऱ्यांसोबत शेअर केले जाईल.',
  'bn_IN': 'জরুরি সহায়তার অনুরোধ করা হবে এবং আপনার অবস্থান চিকিৎসা সহায়তা কর্মীদের সঙ্গে শেয়ার করা হবে.',
},
'SOS activated! Emergency assistance requested.': {
  'en_IN': 'SOS activated! Emergency assistance requested.',
  'hi_IN': 'SOS सक्रिय किया गया! आपातकालीन सहायता का अनुरोध किया गया है।',
  'kn_IN': 'SOS ಸಕ್ರಿಯಗೊಳಿಸಲಾಗಿದೆ! ತುರ್ತು ಸಹಾಯಕ್ಕಾಗಿ ವಿನಂತಿಸಲಾಗಿದೆ.',
  'ta_IN': 'SOS செயல்படுத்தப்பட்டது! அவசர உதவி கோரப்பட்டுள்ளது.',
  'te_IN': 'SOS సక్రియం చేయబడింది! అత్యవసర సహాయం కోసం అభ్యర్థించబడింది.',
  'ml_IN': 'SOS സജീവമാക്കി! അടിയന്തര സഹായത്തിനായി അഭ്യർത്ഥിച്ചു.',
  'mr_IN': 'SOS सक्रिय केले! आपत्कालीन मदतीची विनंती करण्यात आली आहे.',
  'bn_IN': 'SOS সক্রিয় করা হয়েছে! জরুরি সহায়তার জন্য অনুরোধ করা হয়েছে.',
},
'Appointment booking screen will be connected here.': {
  'en_IN': 'Appointment booking screen will be connected here.',
  'hi_IN': 'अपॉइंटमेंट बुकिंग स्क्रीन यहां जोड़ी जाएगी।',
  'kn_IN': 'ಅಪಾಯಿಂಟ್‌ಮೆಂಟ್ ಬುಕಿಂಗ್ ಪರದೆಯನ್ನು ಇಲ್ಲಿ ಸಂಪರ್ಕಿಸಲಾಗುತ್ತದೆ.',
  'ta_IN': 'மருத்துவ ஆலோசனை முன்பதிவு திரை இங்கே இணைக்கப்படும்.',
  'te_IN': 'అపాయింట్‌మెంట్ బుకింగ్ స్క్రీన్ ఇక్కడ అనుసంధానించబడుతుంది.',
  'ml_IN': 'അപ്പോയിന്റ്മെന്റ് ബുക്കിംഗ് സ്‌ക്രീൻ ഇവിടെ ബന്ധിപ്പിക്കും.',
  'mr_IN': 'अपॉइंटमेंट बुकिंग स्क्रीन येथे जोडली जाईल.',
  'bn_IN': 'অ্যাপয়েন্টমেন্ট বুকিং স্ক্রিন এখানে সংযুক্ত করা হবে.',
},

'FIRST AID GUIDANCE': {
  'en_IN': '• Clean the affected area gently with clean water.\n\n'
      '• For a minor cut, apply gentle pressure if there is bleeding and cover it with a clean bandage.\n\n'
      '• For a mild headache, rest in a quiet place and drink enough water.\n\n'
      '• For mild fever, rest, drink fluids and monitor your temperature.\n\n'
      '• For a common cold, rest, stay hydrated and keep yourself comfortable.\n\n'
      'If symptoms become severe, persistent or unusual, seek medical attention.',
  'hi_IN': '• प्रभावित क्षेत्र को साफ पानी से धीरे-धीरे साफ करें।\n\n'
      '• मामूली कट लगने पर, यदि खून बह रहा हो तो हल्का दबाव डालें और साफ पट्टी लगाएं।\n\n'
      '• हल्के सिरदर्द के लिए शांत जगह पर आराम करें और पर्याप्त पानी पिएं।\n\n'
      '• हल्के बुखार में आराम करें, तरल पदार्थ पिएं और अपना तापमान देखते रहें।\n\n'
      '• सामान्य सर्दी-जुकाम में आराम करें, पर्याप्त पानी पिएं और आरामदायक रहें।\n\n'
      'यदि लक्षण गंभीर, लगातार या असामान्य हों, तो चिकित्सा सहायता लें।',
  'kn_IN': '• ಪೀಡಿತ ಪ್ರದೇಶವನ್ನು ಶುದ್ಧ ನೀರಿನಿಂದ ನಿಧಾನವಾಗಿ ಸ್ವಚ್ಛಗೊಳಿಸಿ.\n\n'
      '• ಸಣ್ಣ ಗಾಯವಾಗಿದ್ದರೆ ರಕ್ತಸ್ರಾವವಿದ್ದಾಗ ನಿಧಾನವಾಗಿ ಒತ್ತಡ ನೀಡಿ ಮತ್ತು ಸ್ವಚ್ಛವಾದ ಬ್ಯಾಂಡೇಜ್ ಹಾಕಿ.\n\n'
      '• ಸಣ್ಣ ತಲೆನೋವಿಗೆ ಶಾಂತ ಸ್ಥಳದಲ್ಲಿ ವಿಶ್ರಾಂತಿ ಪಡೆದು ಸಾಕಷ್ಟು ನೀರು ಕುಡಿಯಿರಿ.\n\n'
      '• ಸಣ್ಣ ಜ್ವರಕ್ಕೆ ವಿಶ್ರಾಂತಿ ಪಡೆದು, ದ್ರವಗಳನ್ನು ಕುಡಿಯಿರಿ ಮತ್ತು ನಿಮ್ಮ ತಾಪಮಾನವನ್ನು ಗಮನಿಸಿ.\n\n'
      '• ಸಾಮಾನ್ಯ ಶೀತಕ್ಕೆ ವಿಶ್ರಾಂತಿ ಪಡೆದು, ಸಾಕಷ್ಟು ನೀರು ಕುಡಿಯಿರಿ ಮತ್ತು ಆರಾಮವಾಗಿರಿ.\n\n'
      'ಲಕ್ಷಣಗಳು ತೀವ್ರವಾದರೆ, ನಿರಂತರವಾಗಿದ್ದರೆ ಅಥವಾ ಅಸಾಮಾನ್ಯವಾಗಿದ್ದರೆ ವೈದ್ಯಕೀಯ ಸಹಾಯ ಪಡೆಯಿರಿ.',
  'ta_IN': '• பாதிக்கப்பட்ட பகுதியை சுத்தமான நீரால் மெதுவாக சுத்தம் செய்யவும்.\n\n'
      '• சிறிய வெட்டு ஏற்பட்டால், இரத்தம் வந்தால் மெதுவாக அழுத்தம் கொடுத்து சுத்தமான கட்டு போடவும்.\n\n'
      '• லேசான தலைவலிக்கு அமைதியான இடத்தில் ஓய்வெடுத்து போதுமான தண்ணீர் குடிக்கவும்.\n\n'
      '• லேசான காய்ச்சலுக்கு ஓய்வெடுத்து, திரவங்களை குடித்து, உடல் வெப்பநிலையை கண்காணிக்கவும்.\n\n'
      '• சாதாரண சளிக்கு ஓய்வெடுத்து, நீர்ச்சத்தை பேணி, வசதியாக இருக்கவும்.\n\n'
      'அறிகுறிகள் தீவிரமாகவோ, தொடர்ந்து இருப்பதாகவோ அல்லது அசாதாரணமாகவோ இருந்தால் மருத்துவ உதவியை நாடவும்.',
  'te_IN': '• ప్రభావిత ప్రాంతాన్ని శుభ్రమైన నీటితో మెల్లగా శుభ్రం చేయండి.\n\n'
      '• చిన్న గాయం అయితే, రక్తస్రావం ఉంటే మెల్లగా ఒత్తిడి చేసి శుభ్రమైన బ్యాండేజ్ వేయండి.\n\n'
      '• తేలికపాటి తలనొప్పికి ప్రశాంతమైన ప్రదేశంలో విశ్రాంతి తీసుకుని తగినంత నీరు తాగండి.\n\n'
      '• తేలికపాటి జ్వరానికి విశ్రాంతి తీసుకుని, ద్రవాలు తాగుతూ మీ ఉష్ణోగ్రతను గమనించండి.\n\n'
      '• సాధారణ జలుబుకు విశ్రాంతి తీసుకుని, తగినంత నీరు తాగి సౌకర్యంగా ఉండండి.\n\n'
      'లక్షణాలు తీవ్రంగా, నిరంతరంగా లేదా అసాధారణంగా ఉంటే వైద్య సహాయం పొందండి.',
  'ml_IN': '• ബാധിച്ച ഭാഗം ശുദ്ധമായ വെള്ളത്തിൽ സാവധാനം വൃത്തിയാക്കുക.\n\n'
      '• ചെറിയ മുറിവാണെങ്കിൽ രക്തസ്രാവമുണ്ടെങ്കിൽ സാവധാനം സമ്മർദ്ദം നൽകി വൃത്തിയുള്ള ബാൻഡേജ് ഇടുക.\n\n'
      '• നേരിയ തലവേദനയ്ക്ക് ശാന്തമായ സ്ഥലത്ത് വിശ്രമിക്കുകയും ആവശ്യത്തിന് വെള്ളം കുടിക്കുകയും ചെയ്യുക.\n\n'
      '• നേരിയ പനിയിൽ വിശ്രമിക്കുകയും ദ്രാവകങ്ങൾ കുടിക്കുകയും ശരീര താപനില നിരീക്ഷിക്കുകയും ചെയ്യുക.\n\n'
      '• സാധാരണ ജലദോഷത്തിന് വിശ്രമിക്കുകയും ആവശ്യത്തിന് വെള്ളം കുടിക്കുകയും സുഖകരമായി ഇരിക്കുകയും ചെയ്യുക.\n\n'
      'ലക്ഷണങ്ങൾ ഗുരുതരമോ തുടർച്ചയായതോ അസാധാരണമായതോ ആണെങ്കിൽ വൈദ്യസഹായം തേടുക.',
  'mr_IN': '• प्रभावित भाग स्वच्छ पाण्याने हलक्या हाताने स्वच्छ करा.\n\n'
      '• किरकोळ काप लागल्यास रक्तस्त्राव होत असल्यास हलका दाब द्या आणि स्वच्छ पट्टी लावा.\n\n'
      '• सौम्य डोकेदुखीसाठी शांत ठिकाणी विश्रांती घ्या आणि पुरेसे पाणी प्या.\n\n'
      '• सौम्य तापासाठी विश्रांती घ्या, द्रवपदार्थ प्या आणि तापमानावर लक्ष ठेवा.\n\n'
      '• सामान्य सर्दीसाठी विश्रांती घ्या, पुरेसे पाणी प्या आणि आरामात रहा.\n\n'
      'लक्षणे गंभीर, सतत किंवा असामान्य असल्यास वैद्यकीय मदत घ्या.',
  'bn_IN': '• আক্রান্ত স্থানটি পরিষ্কার পানি দিয়ে আলতোভাবে পরিষ্কার করুন।\n\n'
      '• ছোট কাটা হলে রক্তপাত থাকলে হালকা চাপ দিন এবং পরিষ্কার ব্যান্ডেজ লাগান।\n\n'
      '• হালকা মাথাব্যথার জন্য শান্ত জায়গায় বিশ্রাম নিন এবং পর্যাপ্ত পানি পান করুন।\n\n'
      '• হালকা জ্বরে বিশ্রাম নিন, তরল পান করুন এবং তাপমাত্রা পর্যবেক্ষণ করুন।\n\n'
      '• সাধারণ সর্দির ক্ষেত্রে বিশ্রাম নিন, পর্যাপ্ত পানি পান করুন এবং আরামদায়ক থাকুন।\n\n'
      'উপসর্গ গুরুতর, দীর্ঘস্থায়ী বা অস্বাভাবিক হলে চিকিৎসা সহায়তা নিন।',
},
