  'ml_IN': 'കഴിയുമെങ്കിൽ സുരക്ഷിതവും കാണാവുന്നതുമായ സ്ഥലത്ത് തുടരുക. നിങ്ങളുടെ അടിയന്തര അഭ്യർത്ഥന സജീവമാണ്.',
  'mr_IN': 'शक्य असल्यास सुरक्षित आणि दिसणाऱ्या ठिकाणी रहा. तुमची आपत्कालीन विनंती सक्रिय आहे.',
  'bn_IN': 'সম্ভব হলে নিরাপদ ও দৃশ্যমান স্থানে থাকুন। আপনার জরুরি অনুরোধ সক্রিয় রয়েছে।',
