  'en_IN': 'Emergency medical staff have been notified. Please follow the instructions of the hospital staff.',
  'hi_IN': 'आपातकालीन चिकित्सा कर्मियों को सूचित कर दिया गया है। कृपया अस्पताल के कर्मचारियों के निर्देशों का पालन करें।',
  'kn_IN': 'ತುರ್ತು ವೈದ್ಯಕೀಯ ಸಿಬ್ಬಂದಿಗೆ ಮಾಹಿತಿ ನೀಡಲಾಗಿದೆ. ದಯವಿಟ್ಟು ಆಸ್ಪತ್ರೆಯ ಸಿಬ್ಬಂದಿಯ ಸೂಚನೆಗಳನ್ನು ಅನುಸರಿಸಿ.',
