  'ml_IN': 'അടിയന്തര മെഡിക്കൽ ജീവനക്കാരെ അറിയിച്ചിട്ടുണ്ട്. ആശുപത്രി ജീവനക്കാരുടെ നിർദ്ദേശങ്ങൾ പാലിക്കുക.',
  'mr_IN': 'आपत्कालीन वैद्यकीय कर्मचाऱ्यांना कळवले आहे. कृपया रुग्णालयाच्या कर्मचाऱ्यांच्या सूचनांचे पालन करा.',
  'bn_IN': 'জরুরি চিকিৎসা কর্মীদের জানানো হয়েছে। অনুগ্রহ করে হাসপাতালের কর্মীদের নির্দেশনা অনুসরণ করুন।',
},
