final ValueNotifier<String> appLanguage = ValueNotifier<String>('en_IN');

String get selectedLanguage => appLanguage.value;

set selectedLanguage(String value) {
  appLanguage.value = value;
}

class VoiceAssistant {
  final stt.SpeechToText speech = stt.SpeechToText();

  Future<bool> initialize() async {
    return await speech.initialize();
  }

  Future<void> listen({
    required Function(String) onResult,
    String localeId = 'en_IN',
  }) async {
    final available = await speech.initialize();

    if (!available) {
      return;
    }

    await speech.listen(
      onResult: (result) {
        onResult(result.recognizedWords);
      },
      localeId: localeId,
    );
  }

  Future<void> stop() async {
    await speech.stop();
  }
}

Future<void> main() async {
  WidgetsFlutterBinding.ensureInitialized();

  const AndroidInitializationSettings androidSettings =
      AndroidInitializationSettings('@mipmap/ic_launcher');

  const InitializationSettings initializationSettings =
      InitializationSettings(
    android: androidSettings,
  );

  await flutterLocalNotificationsPlugin.initialize(
    initializationSettings,
  );

  runApp(const RuralTelemedicineApp());
}

  class RuralTelemedicineApp extends StatelessWidget {
  const RuralTelemedicineApp({super.key});

  @override
  Widget build(BuildContext context) {
    return ValueListenableBuilder<String>(
      valueListenable: appLanguage,
      builder: (context, language, child) {
        return MaterialApp(
          debugShowCheckedModeBanner: false,
          title: 'Rural Telemedicine',
          theme: ThemeData(
            primarySwatch: Colors.green,
            scaffoldBackgroundColor: Colors.white,
          ),
          home: SplashScreen(),
        );
      },
    );
  }
}


