class RegistrationScreen extends StatefulWidget {
  const RegistrationScreen({super.key});

  @override
  State<RegistrationScreen> createState() =>
      _RegistrationScreenState();
}

class _RegistrationScreenState
    extends State<RegistrationScreen> {

  final nameController = TextEditingController();
  final dobController = TextEditingController();
  final residentialAddressController = TextEditingController();
  final phoneController = TextEditingController();
  final otpController = TextEditingController();

  String? selectedGender;

  final emergencyNameController =
      TextEditingController();

  final relationshipController =
      TextEditingController();

  final emergencyPhoneController =
      TextEditingController();

  bool otpSent = false;
  bool otpVerified = false;


  // ====================================================
  // SEND OTP
  // ====================================================

  void sendOTP() {

    if (phoneController.text.trim().isEmpty) {

      ScaffoldMessenger.of(context).showSnackBar(
         SnackBar(
          content: Text(
            tr('Please enter your phone number first.', selectedLanguage),
          ),
        ),
      );

      return;
    }

    setState(() {
      otpSent = true;
    });

    // TEST OTP
    ScaffoldMessenger.of(context).showSnackBar(
       SnackBar(
        content: Text(
          tr('OTP sent! Test OTP: 123456', selectedLanguage),
        ),
      ),
    );
  }


  // ====================================================
  // VERIFY OTP
  // ====================================================

  void verifyOTP() {

    if (otpController.text.trim() == '123456') {

      setState(() {
        otpVerified = true;
      });

      ScaffoldMessenger.of(context).showSnackBar(
         SnackBar(
          content: Text(
            tr('Phone number verified successfully!', selectedLanguage),
          ),
        ),
      );

    } else {

      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
            tr('Incorrect OTP. Please try again.', selectedLanguage),
          ),
        ),
      );
    }
  }


  // ====================================================
  // REGISTER
  // ====================================================

Future<void> registerPatient() async {
  if (!otpVerified) {
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text(
          tr(
            'Please verify your phone number first.',
            selectedLanguage,
          ),
        ),
      ),
    );
    return;
  }

  if (
    nameController.text.trim().isEmpty ||
    dobController.text.trim().isEmpty ||
    residentialAddressController.text.trim().isEmpty ||
    phoneController.text.trim().isEmpty ||
    emergencyNameController.text.trim().isEmpty ||
    relationshipController.text.trim().isEmpty ||
    emergencyPhoneController.text.trim().isEmpty ||
    selectedGender == null
  ) {
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text(
          tr(
            'Please fill in all the required details.',
            selectedLanguage,
          ),
        ),
      ),
    );
    return;
  }

  ScaffoldMessenger.of(context).showSnackBar(
    const SnackBar(
      content: Text('Registering patient...'),
    ),
  );

  String formattedDOB = dobController.text.trim();

  try {
    final parts = formattedDOB.split('/');

    if (parts.length == 3) {
      formattedDOB =
          '${parts[2]}-${parts[1].padLeft(2, '0')}-${parts[0].padLeft(2, '0')}';
    }
  } catch (_) {
    // Keep original value if conversion fails
  }

  final result = await ApiService.registerPatient(
    fullName: nameController.text.trim(),
    dateOfBirth: formattedDOB,
    gender: selectedGender!,
    address: residentialAddressController.text.trim(),
    phone: phoneController.text.trim(),
    emergencyContactName:
        emergencyNameController.text.trim(),
    emergencyContactPhone:
        emergencyPhoneController.text.trim(),
  );

  if (result['success'] == true) {
    final prefs = await SharedPreferences.getInstance();

    await prefs.setBool('isRegistered', true);

    await prefs.setString(
      'patientName',
      nameController.text.trim(),
    );

     await prefs.setInt(
       'patientId',
       result['patient_id'],
     );
     print('Saved Patient ID: ${result['patient_id']}');
    if (!mounted) return;

    Navigator.pushReplacement(
      context,
      MaterialPageRoute(
        builder: (context) =>
            const RegistrationSuccessScreen(),
      ),
    );
  } else {
    if (!mounted) return;

    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text(
          result['message'] ??
              'Registration failed. Please try again.',
        ),
      ),
    );
  }
}

  // ====================================================
  // INPUT FIELD
  // ====================================================

  Widget inputField({
    required TextEditingController controller,
    required String hint,
    required IconData icon,
    TextInputType keyboardType =
        TextInputType.text,
        List<TextInputFormatter>? inputFormatters,
  }) {

    return Padding(
      padding: const EdgeInsets.only(bottom: 14),

      child: TextField(
        controller: controller,
        keyboardType: keyboardType,
        inputFormatters: inputFormatters,

        decoration: InputDecoration(

          prefixIcon: Icon(
            icon,
            color: Colors.green,
          ),
          prefixText: keyboardType == TextInputType.phone ? '+91 ' : null,
          hintText: hint,
          

          filled: true,
          fillColor: Colors.white,

          contentPadding:
              const EdgeInsets.symmetric(
            vertical: 16,
            horizontal: 15,
          ),

          border: OutlineInputBorder(
            borderRadius:
                BorderRadius.circular(14),

            borderSide: BorderSide(
              color: Colors.grey.shade300,
            ),
          ),

          enabledBorder:
              OutlineInputBorder(
            borderRadius:
                BorderRadius.circular(14),

            borderSide: BorderSide(
              color: Colors.grey.shade300,
            ),
          ),
        ),
      ),
    );
  }


  // ====================================================
  // BUILD REGISTRATION SCREEN
  // ====================================================

  @override
  Widget build(BuildContext context) {

    return Scaffold(

      backgroundColor: Colors.grey.shade50,

      appBar: AppBar(
  backgroundColor: Colors.green,
  foregroundColor: Colors.white,

  leading: IconButton(
    icon: const Icon(Icons.arrow_back),
    onPressed: () {
  Navigator.pushReplacement(
    context,
    MaterialPageRoute(
      builder: (context) => const LanguageSelectionScreen(),
    ),
  );
},
  ),

  title: Text(
    tr('Registration', selectedLanguage),
    style: const TextStyle(
      color: Colors.white,
      fontWeight: FontWeight.bold,
    ),
  ),
   centerTitle: true,

          actions: [
  PopupMenuButton<String>(
    icon: const Icon(Icons.more_vert),

    onSelected: (value) async {

      // ====================================================
      // AMBULANCE
      // ====================================================

      if (value == 'ambulance') {
        final prefs = await SharedPreferences.getInstance();

        final ambulanceRegistered =
            prefs.getBool('ambulanceRegistered') ?? false;

        if (!mounted) return;

        if (ambulanceRegistered) {
          Navigator.push(
            context,
            MaterialPageRoute(
              builder: (context) =>
                  const AmbulanceDashboardScreen(),
            ),
          );
        } else {
          Navigator.push(
            context,
            MaterialPageRoute(
              builder: (context) =>
                  const AmbulanceRegistrationScreen(),
            ),
          );
        }
      }

      // ====================================================
      // DOCTOR
      // ====================================================

      else if (value == 'doctor') {
        Navigator.push(
          context,
          MaterialPageRoute(
            builder: (context) =>
                const DoctorRegistrationScreen(),
          ),
        );
      }

      // ====================================================
      // HOSPITAL
      // ====================================================

      else if (value == 'hospital') {
        Navigator.push(
          context,
          MaterialPageRoute(
            builder: (context) =>
                const HospitalRegistrationScreen(),
          ),
