  class HomeScreen extends StatefulWidget {
  const HomeScreen({super.key});

  @override
  State<HomeScreen> createState() => _HomeScreenState();
}

class _HomeScreenState extends State<HomeScreen> {
  int currentIndex = 0;

  final VoiceAssistant voiceAssistant = VoiceAssistant();
  Future<void> startVoiceCommand(BuildContext context) async {
    final available = await voiceAssistant.initialize();

    if (!available) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('Voice recognition is not available.'),
        ),
      );
      return;
    }

    await voiceAssistant.listen(
      localeId : selectedLanguage,
      onResult: (command) {
        print("VOICE COMMAND: $command");
        final text = command.toLowerCase();

        if (text.contains('open triage') ||
    text.contains('triage screen') ||
    text.contains('ट्रायेज खोलो') ||
    text.contains('ट्रायेज स्क्रीन') ||
    text.contains('ಟ್ರಯಾಜ್ ತೆರೆಯಿರಿ') ||
    text.contains('ಟ್ರಯಾಜ್ ಸ್ಕ್ರೀನ್') ||
    text.contains('ட்ரையாஜ் திற') ||
    text.contains('ట్రయాజ్ తెరవండి') ||
    text.contains('ട്രയാജ് തുറക്കുക')) {
          Navigator.push(
            context,
            MaterialPageRoute(
              builder: (context) => const TriageScreen(),
            ),
          );

          voiceAssistant.stop();
        }
      },
    );
  }
  Future<Position?> getCurrentLocation() async {
  bool serviceEnabled;
  LocationPermission permission;

  // Check whether location service is turned on
  serviceEnabled = await Geolocator.isLocationServiceEnabled();

  if (!serviceEnabled) {
    return null;
  }

  // Check location permission
  permission = await Geolocator.checkPermission();

  if (permission == LocationPermission.denied) {
    permission = await Geolocator.requestPermission();

    if (permission == LocationPermission.denied) {
      return null;
    }
  }

  if (permission == LocationPermission.deniedForever) {
    return null;
  }

  // Get current location
  return await Geolocator.getCurrentPosition(
    locationSettings: const LocationSettings(
      accuracy: LocationAccuracy.high,
    ),
  );
}

