  // ------------------------------------------------------------
  // TRIAGE CLASSIFICATION
  // ------------------------------------------------------------

  Future<void> analyzeSymptoms() async {
  final symptoms = symptomController.text.trim();

  if (symptoms.isEmpty && uploadedFile == null) {
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text(
          tr(
            'Please describe your symptoms or upload medical information.',
            selectedLanguage,
          ),
        ),
      ),
    );
    return;
  }

  final prefs = await SharedPreferences.getInstance();
  final patientId = prefs.getInt('patientId');

  if (patientId == null) {
    ScaffoldMessenger.of(context).showSnackBar(
      const SnackBar(
        content: Text(
          'Patient information not found. Please register again.',
        ),
      ),
    );
    return;
  }

  showDialog(
    context: context,
    barrierDismissible: false,
    builder: (context) {
      return const AlertDialog(
        content: Row(
          children: [
            CircularProgressIndicator(),
            SizedBox(width: 20),
            Expanded(
              child: Text('Analyzing your symptoms...'),
            ),
          ],
        ),
      );
    },
  );

  final result = await ApiService.analyzeTriage(
    patientId: patientId,
    symptoms: symptoms,
  );

  if (mounted) {
    Navigator.pop(context);
  }

  if (result['success'] != true) {
    if (!mounted) return;

    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text(
          result['message'] ?? 'Triage analysis failed.',
        ),
      ),
    );

    return;
  }

  final riskCode = result['risk_code'];

  String priority;
  String title;
  String message;
  String action;

  if (riskCode == 'Emergency') {
    priority = 'EMERGENCY';

    title = tr(
      'Emergency SOS Required',
      selectedLanguage,
    );

    message = tr(
      'Your symptoms may indicate a medical emergency. Immediate emergency assistance is recommended.',
      selectedLanguage,
    );

    action = 'SOS';
  } else if (riskCode == 'Basic Care') {
    priority = 'FIRST AID';

    title = tr(
      'Basic First Aid Recommended',
      selectedLanguage,
    );

    message = tr(
      'Your symptoms appear suitable for basic first-aid guidance. Follow the recommended steps and monitor your condition.',
      selectedLanguage,
    );

    action = 'FIRST AID';
  } else {
    priority = 'CONSULTATION';

    title = tr(
      'Medical Consultation Recommended',
      selectedLanguage,
    );

    message = tr(
      'Your symptoms may require assessment by a healthcare professional. Consider booking a consultation.',
      selectedLanguage,
    );

    action = 'CONSULTATION';
  }

  if (!mounted) return;

  Navigator.push(
    context,
    MaterialPageRoute(
      builder: (context) => TriageResultScreen(
        priority: priority,
        title: title,
        message: message,
        action: action,
      ),
    ),
  );
}

  // ------------------------------------------------------------
  // HELPER FUNCTION
  // ------------------------------------------------------------

  bool containsAny(
    String text,
    List<String> keywords,
  ) {
    for (final keyword in keywords) {
      if (text.contains(keyword)) {
        return true;
      }
    }

    return false;
  }

