String? doctorLoadError;
@override
void initState() {
  super.initState();
  loadDoctors();
}
Future<void> loadDoctors() async {
  try {
    final result = await ApiService.getDoctors();

    print('DOCTORS FROM API: $result');

    if (!mounted) return;

    setState(() {
      doctors = result;
      isLoadingDoctors = false;
      doctorLoadError = null;
    });
  } catch (e) {
    print('DOCTOR LOAD ERROR: $e');

    if (!mounted) return;

    setState(() {
      isLoadingDoctors = false;
      doctorLoadError = e.toString();
    });
  }
}
