    '06:00 PM',
    '06:30 PM',
  ];

  // ============================================================
  // GET DOCTORS FOR SELECTED SPECIALTY
  // ============================================================

  List<Map<String, dynamic>> get filteredDoctors {
  return doctors
      .where(
        (doctor) =>
            doctor['specialization'] == selectedSpecialty,
      )
      .toList();
}

