              : tr(
                  'Choose Time',
                  selectedLanguage,
                ),

          style: const TextStyle(
            color: darkText,
            fontSize: 20,
            fontWeight: FontWeight.bold,
          ),
        ),
      ),

      body: currentStep == 0
          ? _buildDateScreen()
          : _buildTimeScreen(),
    );
