  // ============================================================
  // SPECIALTY CARD
  // ============================================================

  Widget _buildSpecialtyCard(
    Map<String, dynamic> specialty,
  ) {
    final bool isSelected =
        selectedSpecialty ==
        tr(
          specialty['name'],
          selectedLanguage,
        );

    return GestureDetector(
      onTap: () {

        setState(() {

          selectedSpecialty =
              specialty['name'];

          // Reset doctor whenever specialty changes.
          final matchingDoctors =
              doctors.where(
            (doctor) =>
                doctor['specialty'] ==
                selectedSpecialty,
          ).toList();

          if (matchingDoctors.isNotEmpty) {
            selectedDoctor =
                doctors.indexOf(
              matchingDoctors.first,
            );
          }

          selectedTime = null;
        });
      },

      child: AnimatedContainer(
        duration:
            const Duration(
          milliseconds: 250,
        ),

        width: 145,

        margin:
            const EdgeInsets.only(
          right: 12,
        ),

        padding:
            const EdgeInsets.all(14),

        decoration:
            BoxDecoration(
          color: isSelected
              ? lightBlue
              : Colors.white,

          borderRadius:
              BorderRadius.circular(18),

          border: Border.all(
            color: isSelected
                ? primaryBlue
                : softBorder,

            width:
                isSelected
                    ? 1.8
                    : 1,
          ),

          boxShadow:
              isSelected
                  ? [
                      BoxShadow(
                        color:
                            primaryBlue
                                .withOpacity(
                                    0.10),

                        blurRadius: 10,

                        offset:
                            const Offset(
                          0,
                          4,
                        ),
                      ),
                    ]
                  : [],
        ),

        child: Column(
          mainAxisAlignment:
              MainAxisAlignment.center,

          children: [

            Container(
              height: 48,
              width: 48,

              decoration:
                  BoxDecoration(
                color:
                    specialty['color']
                        .withOpacity(
                            0.12),

                shape:
                    BoxShape.circle,
              ),

              child: Icon(
                specialty['icon'],
                color:
                    specialty['color'],
                size: 25,
              ),
            ),

            const SizedBox(height: 9),

            Text(
              tr(
                specialty['name'],
                selectedLanguage,
              ),

              textAlign:
                  TextAlign.center,

              maxLines: 2,

              overflow:
                  TextOverflow.ellipsis,

              style: TextStyle(
                fontSize: 12.5,

                fontWeight:
                    isSelected
                        ? FontWeight.bold
                        : FontWeight.w500,

                color: isSelected
                    ? primaryBlue
                    : darkText,
              ),
            ),
          ],
        ),
      ),
    );
  }

  // ============================================================
  // DOCTOR CARD
  // ============================================================

  Widget _buildDoctorCard(
  Map<String, dynamic> doctor,
  int index,
) {
  final bool isSelected = selectedDoctor == index;

  // Use a fixed icon/color for database doctors.
  // The doctor information itself comes from PostgreSQL.
  const Color doctorColor = primaryBlue;
  const IconData doctorIcon = Icons.person_rounded;

  final String doctorName =
      doctor['full_name']?.toString() ?? 'Doctor';

  final String specialization =
      doctor['specialization']?.toString() ?? '';

  final int experienceYears =
      int.tryParse(
            doctor['experience_years']?.toString() ?? '',
          ) ??
          0;

  return GestureDetector(
    onTap: () {
      setState(() {
        selectedDoctor = index;
      });
    },
    child: AnimatedContainer(
      duration: const Duration(
        milliseconds: 250,
      ),
      width: 175,
      margin: const EdgeInsets.only(
        right: 12,
      ),
      padding: const EdgeInsets.all(14),
      decoration: BoxDecoration(
        color: isSelected
            ? lightBlue
            : Colors.white,
        borderRadius: BorderRadius.circular(18),
        border: Border.all(
          color: isSelected
              ? primaryBlue
              : softBorder,
          width: isSelected
              ? 1.8
              : 1,
        ),
        boxShadow: isSelected
            ? [
                BoxShadow(
                  color: primaryBlue.withOpacity(
                    0.10,
                  ),
                  blurRadius: 10,
                  offset: const Offset(
                    0,
                    4,
                  ),
                ),
              ]
            : [],
      ),
      child: Column(
        crossAxisAlignment:
            CrossAxisAlignment.start,
        children: [
          Row(
            children: [
              Container(
                height: 48,
                width: 48,
                decoration: BoxDecoration(
                  color: doctorColor.withOpacity(
                    0.12,
                  ),
                  shape: BoxShape.circle,
                ),
                child: const Icon(
                  doctorIcon,
                  color: doctorColor,
                  size: 28,
                ),
              ),
              const Spacer(),
              if (isSelected)
                const Icon(
                  Icons.check_circle_rounded,
                  color: primaryBlue,
                  size: 21,
                ),
            ],
          ),

          const SizedBox(height: 10),

          Text(
            doctorName,
            maxLines: 1,
            overflow: TextOverflow.ellipsis,
            style: const TextStyle(
              fontSize: 14.5,
              fontWeight: FontWeight.bold,
              color: darkText,
            ),
          ),

          const SizedBox(height: 4),

          Text(
            tr(
              specialization,
              selectedLanguage,
            ),
            maxLines: 1,
            overflow: TextOverflow.ellipsis,
            style: const TextStyle(
              fontSize: 11.5,
              color: Colors.grey,
            ),
          ),

          const SizedBox(height: 4),

          Text(
            experienceYears > 0
                ? '$experienceYears Yrs Exp'
                : 'Experience not specified',
            style: const TextStyle(
              fontSize: 11.5,
              color: primaryBlue,
              fontWeight: FontWeight.w600,
            ),
          ),
        ],
      ),
    ),
  );
}

