  // ============================================================
  // DATE POPUP
  // ============================================================

  void _openDatePicker() async {
    final DateTime now =
        DateTime.now();

    final DateTime firstDate =
        DateTime(
      now.year,
      now.month,
      now.day,
    );

    DateTime initialDate =
        selectedDate;

    if (initialDate
        .isBefore(firstDate)) {
      initialDate =
          firstDate;
    }

    final DateTime? pickedDate =
        await showDatePicker(
      context: context,

      initialDate:
          initialDate,

      firstDate:
          firstDate,

      lastDate:
          DateTime(
        now.year,
        now.month + 2,
        now.day,
      ),

      helpText: tr(
        'Select Appointment Date',
        selectedLanguage,
      ),

      cancelText: tr(
        'CANCEL',
        selectedLanguage,
      ),

      confirmText: tr(
        'SELECT',
        selectedLanguage,
      ),
    );

    if (pickedDate != null) {
      setState(() {
        selectedDate =
            pickedDate;
      });
    }
  }

