  // ============================================================
  // CONFIRM APPOINTMENT
  // ============================================================
Future<void> _confirmAppointment() async {
  if (selectedTime == null) {
    return;
  }

  // Get selected doctor from PostgreSQL-loaded doctor list
  final doctor = doctors[selectedDoctor];

  // Get the registered patient's ID
  final prefs = await SharedPreferences.getInstance();
  final patientId = prefs.getInt('patientId');

  if (patientId == null) {
    if (!mounted) return;

    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text(
          tr(
            'Patient information not found. Please register again.',
            selectedLanguage,
          ),
        ),
      ),
    );

    return;
  }

  // Get the real doctor ID from the doctors table
  final doctorId = int.tryParse(
    doctor['doctor_id']?.toString() ?? '',
  );

  if (doctorId == null) {
    if (!mounted) return;

    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text(
          tr(
            'Doctor information is not available.',
            selectedLanguage,
          ),
        ),
      ),
    );

    return;
  }

  // Convert selected date to YYYY-MM-DD
  final appointmentDate =
      '${selectedDate.year.toString().padLeft(4, '0')}-'
      '${selectedDate.month.toString().padLeft(2, '0')}-'
      '${selectedDate.day.toString().padLeft(2, '0')}';

  // Convert selected time such as "09:30 AM" to 24-hour format
  final timeParts = selectedTime!.split(' ');
  final hm = timeParts[0].split(':');

  int hour = int.parse(hm[0]);
  final int minute = int.parse(hm[1]);
  final String period = timeParts[1];

  if (period == 'PM' && hour != 12) {
    hour += 12;
  }

  if (period == 'AM' && hour == 12) {
    hour = 0;
  }

  final startTime =
      '${hour.toString().padLeft(2, '0')}:'
      '${minute.toString().padLeft(2, '0')}:00';

  // Every appointment slot is 30 minutes
  final startDateTime = DateTime(
    selectedDate.year,
    selectedDate.month,
    selectedDate.day,
    hour,
    minute,
  );

  final endDateTime =
      startDateTime.add(const Duration(minutes: 30));

  final endTime =
      '${endDateTime.hour.toString().padLeft(2, '0')}:'
      '${endDateTime.minute.toString().padLeft(2, '0')}:00';

    print('PATIENT ID: $patientId');
    print('DOCTOR DATA: $doctor');
    print('DOCTOR ID: $doctorId');
    print('APPOINTMENT DATE: $appointmentDate');
    print('START TIME: $startTime');
    print('END TIME: $endTime');
  // Send appointment to Flask
  final result = await ApiService.createAppointment(
    patientId: patientId,
    doctorId: doctorId,
    appointmentDate: appointmentDate,
    startTime: startTime,
    endTime: endTime,
    consultationMode: 'Online',
    reasonForVisit: null,
  );

  if (!mounted) return;

  // Booking failed
  if (result['success'] != true) {
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text(
          result['message'] ??
              tr(
                'Failed to book appointment.',
                selectedLanguage,
              ),
        ),
      ),
    );

    return;
  }

  // Booking succeeded
  final appointmentId = result['appointment_id'];

  showDialog(
    context: context,
    barrierDismissible: false,
    builder: (context) {
      return AlertDialog(
        shape: RoundedRectangleBorder(
          borderRadius: BorderRadius.circular(22),
        ),

        title: Row(
          children: [
            Container(
              height: 42,
              width: 42,
              decoration: const BoxDecoration(
                color: lightBlue,
                shape: BoxShape.circle,
              ),
              child: const Icon(
                Icons.check_rounded,
                color: primaryBlue,
              ),
            ),

            const SizedBox(width: 12),

            Expanded(
              child: Text(
                tr(
                  'Appointment Confirmed',
                  selectedLanguage,
                ),
                style: const TextStyle(
                  fontSize: 18,
                  fontWeight: FontWeight.bold,
                  color: darkText,
                ),
              ),
            ),
          ],
        ),

        content: Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            _summaryRow(
              tr(
                'Doctor',
                selectedLanguage,
              ),
              doctor['full_name']?.toString() ?? 'Doctor',
            ),

            const SizedBox(height: 12),

            _summaryRow(
              tr(
                'Specialty',
                selectedLanguage,
              ),
              tr(
                selectedSpecialty,
                selectedLanguage,
              ),
            ),

            const SizedBox(height: 12),

            _summaryRow(
              tr(
                'Date',
                selectedLanguage,
              ),
              _formattedSelectedDate(),
            ),

            const SizedBox(height: 12),

            _summaryRow(
              tr(
                'Time',
                selectedLanguage,
              ),
              selectedTime!,
            ),

            const SizedBox(height: 12),

            _summaryRow(
              'Appointment ID',
              appointmentId.toString(),
            ),

            const SizedBox(height: 15),

            Text(
              tr(
                'Your online appointment has been scheduled successfully.',
                selectedLanguage,
              ),
              style: const TextStyle(
                fontSize: 13,
                color: Colors.grey,
              ),
            ),
          ],
        ),

        actions: [
          TextButton(
            onPressed: () {
              Navigator.pop(context);

              Navigator.pushAndRemoveUntil(
                context,
                MaterialPageRoute(
                  builder: (context) => const HomeScreen(),
                ),
                (route) => false,
              );
            },

            child: Text(
              tr(
                'DONE',
                selectedLanguage,
              ),
              style: const TextStyle(
                color: primaryBlue,
                fontWeight: FontWeight.bold,
              ),
            ),
          ),
        ],
      );
    },
  );
}
