class AppointmentsScreen extends StatefulWidget {
  final VoidCallback onBack;

  const AppointmentsScreen({
    super.key,
    required this.onBack,
  });

  @override
  State<AppointmentsScreen> createState() => _AppointmentsScreenState();
}

class _AppointmentsScreenState extends State<AppointmentsScreen> {
  bool showUpcoming = true;
   bool isLoading = true;
     List<Map<String, dynamic>> appointments = [];
   List<Map<String, dynamic>> get upcomingAppointments {
  final now = DateTime.now();

  return appointments.where((appointment) {
    try {
      final date = appointment['date'].toString();
      final time = appointment['time'].toString();
      final status = appointment['status'].toString();

      final appointmentDateTime =
          DateTime.parse('$date $time');

      return appointmentDateTime.isAfter(now) &&
          status == 'Scheduled';
    } catch (e) {
      return false;
    }
  }).toList();
}

List<Map<String, dynamic>> get pastAppointments {
  final now = DateTime.now();

  return appointments.where((appointment) {
    try {
      final date = appointment['date'].toString();
      final time = appointment['time'].toString();

      final appointmentDateTime =
          DateTime.parse('$date $time');

      return !appointmentDateTime.isAfter(now) &&
    appointment['status'].toString() != 'Cancelled';
    } catch (e) {
      return false;
    }
  }).toList();
}
     Future<void> loadAppointments() async {
  try {
    final prefs = await SharedPreferences.getInstance();
    final patientId = prefs.getInt('patientId');

    if (patientId == null) {
      if (!mounted) return;

      setState(() {
        isLoading = false;
        appointments = [];
      });

      return;
    }

    final data = await ApiService.getAppointments(patientId);

    if (!mounted) return;

    setState(() {
  appointments = data.map((appointment) {
  return {
    'appointment_id': appointment['appointment_id'],
    'doctor': appointment['doctor_name'],
    'specialty': appointment['specialization'],
    'qualification': appointment['qualification'],
    'experience_years': appointment['experience_years'],
    'date': appointment['appointment_date'],
    'time': appointment['start_time'],
    'end_time': appointment['end_time'],
    'consultation_mode': appointment['consultation_mode'],
    'reason_for_visit': appointment['reason_for_visit'],
    'status': appointment['status'],
    'icon': Icons.calendar_today,
  };
}).toList();

  isLoading = false;
});
  } catch (e) {
    if (!mounted) return;

    setState(() {
      isLoading = false;
      appointments = [];
    });

    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text('Failed to load appointments'),
      ),
    );
  }
}
  static const Color primaryBlue = Color(0xFF4F7FBF);
  static const Color lightBlue = Color(0xFFEAF2FA);
  static const Color veryLightBlue = Color(0xFFF7FAFD);
  static const Color darkBlue = Color(0xFF2D5688);
  static const Color softBorder = Color(0xFFD9E5F1);
  static const Color greyText = Color(0xFF6E7F91);


