    void confirmCancel(Map<String, dynamic> appointment) {
    showDialog(
      context: context,
      builder: (dialogContext) {
        return AlertDialog(
          backgroundColor: Colors.white,
          shape: RoundedRectangleBorder(
            borderRadius: BorderRadius.circular(20),
          ),
          title: Text(
            tr('Cancel Appointment?', selectedLanguage),
            style: TextStyle(
              color: darkBlue,
              fontWeight: FontWeight.bold,
            ),
          ),
          content: Text(
            tr('This appointment will be permanently removed from your appointments.', selectedLanguage),
          ),
          actions: [
            TextButton(
              onPressed: () {
                Navigator.pop(dialogContext);
              },
              child: Text(
                tr('Keep', selectedLanguage),
                style: TextStyle(color: greyText),
              ),
            ),
            ElevatedButton(
              style: ElevatedButton.styleFrom(
                backgroundColor: primaryBlue,
                foregroundColor: Colors.white,
              ),
              onPressed: () async {
  Navigator.pop(dialogContext);


  final appointmentId = appointment['appointment_id'];

  if (appointmentId == null) {
    ScaffoldMessenger.of(context).showSnackBar(
      const SnackBar(
        content: Text('Appointment ID not found'),
      ),
    );
    return;
  }

  final result = await ApiService.cancelAppointment(
    appointmentId: appointmentId,
  );

  if (!mounted) return;

  if (result['success'] == true) {
    await loadAppointments();

    if (!mounted) return;

    ScaffoldMessenger.of(context).showSnackBar(
      const SnackBar(
        content: Text('Appointment cancelled successfully'),
      ),
    );
  } else {
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text(
          result['message'] ?? 'Failed to cancel appointment',
        ),
      ),
    );
  }
},
              child:  Text(tr('Cancel Appointment', selectedLanguage)),
            ),
          ],
        );
      },
    );
  }

