class AmbulanceTrackingScreen extends StatefulWidget {
  const AmbulanceTrackingScreen({super.key});

  @override
  State<AmbulanceTrackingScreen> createState() =>
      _AmbulanceTrackingScreenState();
}

class _AmbulanceTrackingScreenState
    extends State<AmbulanceTrackingScreen> {
      int remainingMinutes = 6;
  Timer? trackingTimer;  
   @override
void initState() {
  super.initState();

  trackingTimer = Timer.periodic(
    const Duration(seconds: 5),
    (timer) async {
      if (!mounted) return;

      if (remainingMinutes > 0) {
        setState(() {
          remainingMinutes--;
        });
      } else {
        timer.cancel();

        await updateSOSToArrived();
      }
    },
  );
}
Future<void> updateSOSToArrived() async {
  final prefs = await SharedPreferences.getInstance();

  final sosId = prefs.getInt('sosId');

  if (sosId == null) {
    debugPrint('SOS ID not found');
    return;
  }

  final result = await ApiService.updateSOSStatus(
    sosId: sosId,
    status: 'Arrived',
  );

  if (result['success'] == true) {
    debugPrint('SOS status changed to Arrived');

    if (!mounted) return;

    Navigator.pushReplacement(
      context,
      MaterialPageRoute(
        builder: (context) => const PatientPickupScreen(),
      ),
    );
  } else {
    debugPrint(
      'Failed to update SOS status: ${result['message']}',
    );
  }
}
  @override
  void dispose() {
    trackingTimer?.cancel();
    super.dispose();
  }

