      _EscalatingEmergencyScreenState();
}

class _EscalatingEmergencyScreenState
    extends State<EscalatingEmergencyScreen> {
  Timer? escalationTimer;

  @override
void initState() {
  super.initState();

  updateSOSToEnroute();
}
Future<void> updateSOSToEnroute() async {
  final prefs = await SharedPreferences.getInstance();

  final sosId = prefs.getInt('sosId');

  if (sosId == null) {
    debugPrint('SOS ID not found');
    return;
  }

  // Keep the escalation screen visible for 5 seconds.
  await Future.delayed(
    const Duration(seconds: 5),
  );

  if (!mounted) return;

  final result = await ApiService.updateSOSStatus(
    sosId: sosId,
    status: 'Enroute',
  );

  if (result['success'] == true) {
    debugPrint('SOS status changed to Enroute');

    if (!mounted) return;

    Navigator.pushReplacement(
      context,
      MaterialPageRoute(
        builder: (context) =>
            const SOSResponseReceivedScreen(),
      ),
    );
  } else {
    debugPrint(
      'Failed to update SOS status: ${result['message']}',
    );
  }
}
  @override
  void dispose() {
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: const Color(0xFFF7FAFC),
      appBar: AppBar(
        backgroundColor: Colors.white,
