class HospitalArrivalScreen extends StatefulWidget {
  const HospitalArrivalScreen({super.key});

  @override
  State<HospitalArrivalScreen> createState() =>
      _HospitalArrivalScreenState();
}

class _HospitalArrivalScreenState
    extends State<HospitalArrivalScreen> {

  bool isClosingSOS = false;

  Future<void> completeEmergency() async {
    setState(() {
      isClosingSOS = true;
    });

    final prefs = await SharedPreferences.getInstance();
    final sosId = prefs.getInt('sosId');

    if (sosId == null) {
      setState(() {
        isClosingSOS = false;
      });

      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('SOS information not found'),
        ),
      );

      return;
    }

    final result = await ApiService.updateSOSStatus(
      sosId: sosId,
      status: 'Closed',
    );

    if (!mounted) return;

    if (result['success'] == true) {
      debugPrint('SOS status changed to Closed');

      Navigator.pushReplacement(
        context,
        MaterialPageRoute(
          builder: (context) => const CompletedScreen(),
        ),
      );
    } else {
      setState(() {
        isClosingSOS = false;
      });

      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
            result['message'] ?? 'Failed to complete emergency',
          ),
        ),
      );
    }
  }

