class AmbulanceRegistrationScreen extends StatefulWidget {
  const AmbulanceRegistrationScreen({super.key});

  @override
  State<AmbulanceRegistrationScreen> createState() =>
      _AmbulanceRegistrationScreenState();
}

class _AmbulanceRegistrationScreenState
    extends State<AmbulanceRegistrationScreen> {
  final TextEditingController teamNameController = TextEditingController();
  final TextEditingController phoneController = TextEditingController();
  final TextEditingController otpController = TextEditingController();
  final TextEditingController ambulanceNumberController =
      TextEditingController();
  final TextEditingController driverNameController = TextEditingController();

  bool otpSent = false;
  bool otpVerified = false;

  @override
  void dispose() {
    teamNameController.dispose();
    phoneController.dispose();
    otpController.dispose();
    ambulanceNumberController.dispose();
    driverNameController.dispose();
    super.dispose();
  }

  void sendOTP() {
    if (phoneController.text.length != 10) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('Please enter a valid 10-digit phone number.'),
        ),
      );
      return;
    }

    setState(() {
      otpSent = true;
    });

    ScaffoldMessenger.of(context).showSnackBar(
      const SnackBar(
        content: Text('OTP sent successfully.'),
      ),
    );
  }

  void verifyOTP() {
    if (otpController.text == '123456') {
      setState(() {
        otpVerified = true;
      });

      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('Phone number verified successfully.'),
        ),
      );
    } else {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('Invalid OTP. Please try again.'),
        ),
      );
    }
  }

  Future<void> registerAmbulance() async {
  if (teamNameController.text.trim().isEmpty ||
      phoneController.text.length != 10 ||
      !otpVerified ||
      ambulanceNumberController.text.trim().isEmpty ||
      driverNameController.text.trim().isEmpty) {
    ScaffoldMessenger.of(context).showSnackBar(
      const SnackBar(
        content: Text('Please complete all required fields.'),
      ),
    );
    return;
  }

  final prefs = await SharedPreferences.getInstance();

  // Save ambulance registration details
  await prefs.setBool('ambulanceRegistered', true);

  await prefs.setString(
    'ambulanceTeamName',
    teamNameController.text.trim(),
  );

  await prefs.setString(
    'ambulancePhone',
    phoneController.text.trim(),
  );

  await prefs.setString(
    'ambulanceNumber',
    ambulanceNumberController.text.trim(),
  );

  await prefs.setString(
    'ambulanceDriverName',
    driverNameController.text.trim(),
  );

  Navigator.push(
    context,
    MaterialPageRoute(
      builder: (context) => const AmbulanceRegistrationSuccessScreen(),
    ),
  );
}

  Widget inputField({
    required String label,
    required String hint,
    required TextEditingController controller,
    TextInputType keyboardType = TextInputType.text,
    bool enabled = true,
  }) {
    return TextField(
      controller: controller,
      enabled: enabled,
      keyboardType: keyboardType,
      decoration: InputDecoration(
        labelText: label,
        hintText: hint,
        filled: true,
        fillColor: Colors.white,
        border: OutlineInputBorder(
          borderRadius: BorderRadius.circular(14),
          borderSide: BorderSide.none,
        ),
        enabledBorder: OutlineInputBorder(
          borderRadius: BorderRadius.circular(14),
          borderSide: BorderSide(
            color: Colors.grey.shade200,
          ),
        ),
        focusedBorder: OutlineInputBorder(
          borderRadius: BorderRadius.circular(14),
          borderSide: const BorderSide(
            color: Colors.teal,
            width: 2,
          ),
        ),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: const Color(0xFFF7FAFC),
      appBar: AppBar(
        backgroundColor: Colors.white,
        elevation: 0,
        leading: IconButton(
          icon: const Icon(
            Icons.arrow_back_ios_new_rounded,
            color: Colors.black87,
          ),
          onPressed: () {
            Navigator.pop(context);
          },
        ),
        title: const Text(
          'Ambulance Registration',
          style: TextStyle(
            color: Colors.black87,
            fontWeight: FontWeight.bold,
          ),
        ),
        centerTitle: true,
      ),
      body: SingleChildScrollView(
        padding: const EdgeInsets.all(20),
        child: Column(
          children: [
            const SizedBox(height: 10),

            // Ambulance icon
            Container(
              width: 100,
              height: 100,
              decoration: BoxDecoration(
                color: Colors.red.shade50,
                shape: BoxShape.circle,
              ),
              child: Icon(
                Icons.local_shipping_rounded,
                color: Colors.red.shade700,
                size: 58,
              ),
            ),

            const SizedBox(height: 20),

            const Text(
              'Register Ambulance Service',
              textAlign: TextAlign.center,
              style: TextStyle(
                fontSize: 25,
                fontWeight: FontWeight.bold,
                color: Color(0xFF202938),
              ),
            ),

            const SizedBox(height: 10),

            const Text(
              'Register your ambulance team to receive and respond to emergency requests.',
              textAlign: TextAlign.center,
              style: TextStyle(
                fontSize: 14,
                color: Colors.black54,
                height: 1.5,
              ),
            ),

            const SizedBox(height: 30),

            inputField(
              label: 'Ambulance Team / Staff Name',
              hint: 'Enter team or staff name',
              controller: teamNameController,
            ),

            const SizedBox(height: 16),

            inputField(
              label: 'Phone Number',
              hint: 'Enter 10-digit phone number',
              controller: phoneController,
              keyboardType: TextInputType.phone,
              enabled: !otpVerified,
            ),

            const SizedBox(height: 12),

            if (!otpVerified)
              SizedBox(
                width: double.infinity,
                height: 50,
                child: OutlinedButton(
                  onPressed: sendOTP,
                  style: OutlinedButton.styleFrom(
                    foregroundColor: Colors.teal,
                    side: const BorderSide(
                      color: Colors.teal,
                    ),
                    shape: RoundedRectangleBorder(
                      borderRadius: BorderRadius.circular(14),
                    ),
                  ),
                  child: Text(
                    otpSent ? 'Resend OTP' : 'Send OTP',
                    style: const TextStyle(
                      fontWeight: FontWeight.bold,
                    ),
                  ),
                ),
              ),

            if (otpSent && !otpVerified) ...[
              const SizedBox(height: 16),

              inputField(
                label: 'OTP',
                hint: 'Enter 6-digit OTP',
                controller: otpController,
                keyboardType: TextInputType.number,
              ),

              const SizedBox(height: 12),

              SizedBox(
                width: double.infinity,
                height: 50,
                child: ElevatedButton(
                  onPressed: verifyOTP,
                  style: ElevatedButton.styleFrom(
                    backgroundColor: const Color(0xFF10192F),
                    foregroundColor: Colors.white,
                    shape: RoundedRectangleBorder(
                      borderRadius: BorderRadius.circular(14),
                    ),
                  ),
                  child: const Text(
                    'Verify OTP',
                    style: TextStyle(
                      fontWeight: FontWeight.bold,
                    ),
                  ),
                ),
              ),
            ],

            if (otpVerified) ...[
              const SizedBox(height: 10),

              const Row(
                children: [
                  Icon(
                    Icons.verified_rounded,
                    color: Colors.green,
                    size: 22,
                  ),
                  SizedBox(width: 8),
                  Text(
                    'Phone number verified',
                    style: TextStyle(
                      color: Colors.green,
                      fontWeight: FontWeight.bold,
                    ),
                  ),
                ],
              ),
            ],

            const SizedBox(height: 20),

            inputField(
              label: 'Ambulance / Vehicle Number',
              hint: 'Enter vehicle number',
              controller: ambulanceNumberController,
            ),

            const SizedBox(height: 16),

            inputField(
              label: 'Driver Name',
              hint: 'Enter driver name',
              controller: driverNameController,
            ),

            const SizedBox(height: 30),

            SizedBox(
              width: double.infinity,
              height: 55,
              child: ElevatedButton(
                onPressed: registerAmbulance,
                style: ElevatedButton.styleFrom(
                  backgroundColor: const Color(0xFF10192F),
                  foregroundColor: Colors.white,
                  shape: RoundedRectangleBorder(
                    borderRadius: BorderRadius.circular(14),
                  ),
                ),
                child: const Text(
                  'Register Ambulance',
                  style: TextStyle(
                    fontSize: 16,
                    fontWeight: FontWeight.bold,
                  ),
                ),
              ),
            ),

            const SizedBox(height: 20),

            const Text(
              'Emergency ambulance registration and access will be managed securely.',
              textAlign: TextAlign.center,
              style: TextStyle(
                fontSize: 12,
                color: Colors.grey,
              ),
            ),
          ],
        ),
      ),
    );
  }
}

