// ======================================================
// AMBULANCE NAVIGATE TO PATIENT
// ======================================================

class AmbulanceNavigateToPatientScreen extends StatefulWidget {
  const AmbulanceNavigateToPatientScreen({super.key});

  @override
  State<AmbulanceNavigateToPatientScreen> createState() =>
      _AmbulanceNavigateToPatientScreenState();
}
class _AmbulanceNavigateToPatientScreenState
    extends State<AmbulanceNavigateToPatientScreen> {
  Position? ambulancePosition;

  bool loadingLocation = true;
  bool navigationStarted = false;

  // TEMPORARY DEMO PATIENT LOCATION
  // We will replace this with the patient's actual SOS GPS location later.
  final LatLng patientLocation = LatLng(
    9.9312,
    76.2673,
  );

  @override
  void initState() {
    super.initState();
    getAmbulanceLocation();
  }

  Future<void> getAmbulanceLocation() async {
    final position = await getCurrentLocation();

    if (!mounted) return;

    setState(() {
      ambulancePosition = position;
      loadingLocation = false;
    });
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: const Color(0xFFF7FAFC),

      appBar: AppBar(
        backgroundColor: Colors.teal,
        foregroundColor: Colors.white,
        automaticallyImplyLeading: false,

        title: const Text(
          'Navigate to Patient',
          style: TextStyle(
            fontWeight: FontWeight.bold,
          ),
        ),

        centerTitle: true,
      ),

      body: Column(
        children: [

          // MAP
          Expanded(
            child: loadingLocation
                ? const Center(
                    child: CircularProgressIndicator(
                      color: Colors.teal,
                    ),
                  )
                : FlutterMap(
                    options: MapOptions(
                      initialCenter: patientLocation,
                      initialZoom: 13,
                    ),

                    children: [

                      // MAP TILES
                      TileLayer(
                        urlTemplate:
                            'https://tile.openstreetmap.org/{z}/{x}/{y}.png',
                        userAgentPackageName:
                            'com.example.rural_telemedicine',
                      ),

                      // ROUTE LINE
                      if (ambulancePosition != null)
                        PolylineLayer(
                          polylines: [
                            Polyline(
                              points: [
                                LatLng(
                                  ambulancePosition!.latitude,
                                  ambulancePosition!.longitude,
                                ),
                                patientLocation,
                              ],
                              strokeWidth: 5,
                              color: Colors.teal,
                            ),
                          ],
                        ),

                      // MARKERS
                      MarkerLayer(
                        markers: [

                          // AMBULANCE
                          if (ambulancePosition != null)
                            Marker(
                              point: LatLng(
                                ambulancePosition!.latitude,
                                ambulancePosition!.longitude,
                              ),
                              width: 60,
                              height: 60,
                              child: Container(
                                decoration: BoxDecoration(
                                  color: Colors.teal,
                                  shape: BoxShape.circle,
                                  boxShadow: [
                                    BoxShadow(
                                      color: Colors.black.withOpacity(0.2),
                                      blurRadius: 8,
                                    ),
                                  ],
                                ),

                                child: const Icon(
                                  Icons.local_shipping_rounded,
                                  color: Colors.white,
                                  size: 32,
                                ),
                              ),
                            ),

                          // PATIENT
                          Marker(
                            point: patientLocation,
                            width: 60,
                            height: 60,
                            child: Container(
                              decoration: BoxDecoration(
                                color: Colors.red,
                                shape: BoxShape.circle,
                                boxShadow: [
                                  BoxShadow(
                                    color: Colors.black.withOpacity(0.2),
                                    blurRadius: 8,
                                  ),
                                ],
                              ),

                              child: const Icon(
                                Icons.location_on_rounded,
                                color: Colors.white,
                                size: 32,
                              ),
                            ),
                          ),
                        ],
                      ),
                    ],
                  ),
          ),

          // INFORMATION PANEL
          Container(
            width: double.infinity,
            padding: const EdgeInsets.all(18),

            decoration: const BoxDecoration(
              color: Colors.white,

              borderRadius: BorderRadius.only(
                topLeft: Radius.circular(22),
                topRight: Radius.circular(22),
              ),
            ),

            child: Column(
              crossAxisAlignment: CrossAxisAlignment.stretch,

              children: [

                const Row(
                  children: [

                    Icon(
                      Icons.emergency_rounded,
                      color: Colors.red,
                      size: 25,
                    ),

                    SizedBox(width: 10),

                    Text(
                      'Emergency Patient',
                      style: TextStyle(
                        fontSize: 19,
                        fontWeight: FontWeight.bold,
                      ),
                    ),
                  ],
                ),

                const SizedBox(height: 12),

                Row(
                  children: [

                    const Icon(
                      Icons.location_on_rounded,
                      color: Colors.red,
                    ),

                    const SizedBox(width: 8),

                    const Expanded(
                      child: Text(
                        'Patient location received',
                        style: TextStyle(
                          fontWeight: FontWeight.w600,
                        ),
                      ),
                    ),
                  ],
                ),

                const SizedBox(height: 8),

                Row(
                  children: [

                    const Icon(
                      Icons.local_shipping_rounded,
                      color: Colors.teal,
                    ),

                    const SizedBox(width: 8),

                    Expanded(
                      child: Text(
                        navigationStarted
                            ? 'Navigation in progress'
                            : 'Ready to navigate',
                        style: TextStyle(
                          color: navigationStarted
                              ? Colors.teal
                              : Colors.grey.shade700,
                          fontWeight: FontWeight.w600,
                        ),
                      ),
                    ),
                  ],
                ),

                const SizedBox(height: 15),

                // START NAVIGATION
                SizedBox(
                  height: 52,

                  child: ElevatedButton.icon(
                    onPressed: () async {
                      ScaffoldMessenger.of(context).showSnackBar(
                       const SnackBar(
                      content: Text(
                       'Navigation started to patient location.',
                     ),
                   ),
                );

                  await Future.delayed(
                   const Duration(seconds: 10),
                  );

                   if (!mounted) return;
                  Navigator.push(
                    context,
                    MaterialPageRoute(
                     builder: (context) =>
                      const AmbulanceArrivedAtPatientScreen(),
                  ),
               );
           },
                    icon: const Icon(
                      Icons.navigation_rounded,
                    ),

                    label: const Text(
                      'Start Navigation',
                      style: TextStyle(
                        fontSize: 16,
                        fontWeight: FontWeight.bold,
                      ),
                    ),

                    style: ElevatedButton.styleFrom(
                      backgroundColor: Colors.teal,
                      foregroundColor: Colors.white,

                      shape: RoundedRectangleBorder(
                        borderRadius: BorderRadius.circular(15),
                      ),
                    ),
                  ),
                ),

                const SizedBox(height: 10),

                // BACK
                SizedBox(
                  height: 48,

                  child: OutlinedButton(
                    onPressed: () {
                      Navigator.pop(context);
                    },

                    child: const Text(
                      'Back',
                      style: TextStyle(
                        fontSize: 15,
                        fontWeight: FontWeight.bold,
                      ),
                    ),
                  ),
                ),
              ],
            ),
          ),
        ],
      ),
    );
  }
}
