  @override
  State<AmbulanceStatusScreen> createState() =>
      _AmbulanceStatusScreenState();
}

class _AmbulanceStatusScreenState
    extends State<AmbulanceStatusScreen> {

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: const Color(0xFFF7FAFC),
      appBar: AppBar(
        backgroundColor: Colors.orange,
        foregroundColor: Colors.white,
        title: const Text(
          'Ambulance Status',
          style: TextStyle(
            fontWeight: FontWeight.bold,
          ),
        ),
        centerTitle: true,
      ),
      body: Padding(
        padding: const EdgeInsets.all(20),
        child: Column(
          children: [
            const SizedBox(height: 20),

            const Icon(
              Icons.local_shipping_rounded,
              color: Colors.orange,
              size: 80,
            ),

            const SizedBox(height: 20),

            const Text(
              'Set Ambulance Availability',
              textAlign: TextAlign.center,
              style: TextStyle(
                fontSize: 24,
                fontWeight: FontWeight.bold,
              ),
            ),

            const SizedBox(height: 10),

            const Text(
              'Choose the current status of this ambulance.',
              textAlign: TextAlign.center,
              style: TextStyle(
                color: Colors.black54,
                fontSize: 15,
              ),
            ),

            const SizedBox(height: 30),

            _statusOption(
              'Available',
              'Ready to receive emergency requests',
              Colors.green,
              Icons.check_circle_rounded,
            ),

            const SizedBox(height: 15),

            _statusOption(
              'On Emergency',
              'Currently handling an emergency',
              Colors.red,
              Icons.emergency_rounded,
            ),

            const SizedBox(height: 15),

            _statusOption(
              'Unavailable',
              'Not available for emergency requests',
              Colors.grey,
              Icons.block_rounded,
            ),

            const Spacer(),

            SizedBox(
              width: double.infinity,
              child: ElevatedButton(
                onPressed: () {
                  ScaffoldMessenger.of(context).showSnackBar(
                    SnackBar(
                      content: Text(
                        'Ambulance status set to ${ambulanceStatus.value}.',
                      ),
                    ),
                  );
                },
                style: ElevatedButton.styleFrom(
                  backgroundColor: Colors.orange,
                  foregroundColor: Colors.white,
                  padding: const EdgeInsets.symmetric(
                    vertical: 16,
                  ),
                  shape: RoundedRectangleBorder(
                    borderRadius: BorderRadius.circular(15),
                  ),
                ),
                child: const Text(
                  'Save Status',
                  style: TextStyle(
                    fontSize: 16,
                    fontWeight: FontWeight.bold,
                  ),
                ),
              ),
            ),

            const SizedBox(height: 10),
          ],
        ),
      ),
    );
  }

  Widget _statusOption(
    String status,
    String description,
    Color color,
    IconData icon,
  ) {
    final bool isSelected = ambulanceStatus.value == status;

    return InkWell(
      onTap: () {
        ambulanceStatus.value = status;
      },
      borderRadius: BorderRadius.circular(18),
      child: Container(
        width: double.infinity,
        padding: const EdgeInsets.all(18),
        decoration: BoxDecoration(
          color: isSelected
              ? color.withOpacity(0.08)
              : Colors.white,
          borderRadius: BorderRadius.circular(18),
          border: Border.all(
            color: isSelected
                ? color
                : Colors.grey.shade200,
            width: isSelected ? 2 : 1,
          ),
        ),
        child: Row(
          children: [
            Icon(
              icon,
              color: color,
              size: 35,
            ),
            const SizedBox(width: 15),
            Expanded(
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text(
                    status,
                    style: TextStyle(
                      fontSize: 17,
                      fontWeight: FontWeight.bold,
                      color: color,
                    ),
                  ),
                  const SizedBox(height: 5),
                  Text(
                    description,
                    style: const TextStyle(
                      fontSize: 13,
                      color: Colors.black54,
                    ),
                  ),
                ],
              ),
            ),
            Icon(
              isSelected
                  ? Icons.radio_button_checked
                  : Icons.radio_button_unchecked,
              color: color,
            ),
          ],
        ),
      ),
    );
  }
}
class AmbulanceProfileScreen extends StatefulWidget {
  const AmbulanceProfileScreen({super.key});

  @override
  State<AmbulanceProfileScreen> createState() =>
      _AmbulanceProfileScreenState();
}

class _AmbulanceProfileScreenState
    extends State<AmbulanceProfileScreen> {
  String teamName = 'Ambulance Team';
  String phoneNumber = '+91 XXXXX XXXXX';
  String vehicleNumber = 'KL XX XX XXXX';
  String driverName = 'Driver Name';

  @override
  void initState() {
    super.initState();
    loadAmbulanceDetails();
  }

  Future<void> loadAmbulanceDetails() async {
    final prefs = await SharedPreferences.getInstance();

    if (!mounted) return;

    setState(() {
      teamName =
          prefs.getString('ambulanceTeamName') ??
          'Ambulance Team';

      final phone =
          prefs.getString('ambulancePhone') ?? '';

      phoneNumber = phone.isNotEmpty
          ? '+91 $phone'
          : '+91 XXXXX XXXXX';

      vehicleNumber =
          prefs.getString('ambulanceNumber') ??
          'KL XX XX XXXX';

      driverName =
          prefs.getString('ambulanceDriverName') ??
          'Driver Name';
    });
  }

  Future<void> editProfile() async {
    final teamController =
        TextEditingController(text: teamName);

    final phoneController = TextEditingController(
      text: phoneNumber.replaceFirst('+91 ', ''),
    );

    final vehicleController =
        TextEditingController(text: vehicleNumber);

    final driverController =
        TextEditingController(text: driverName);

    final result = await showDialog<bool>(
      context: context,
      builder: (context) {
        return AlertDialog(
          title: const Text(
            'Edit Ambulance Profile',
            style: TextStyle(
              fontWeight: FontWeight.bold,
            ),
          ),
          content: SingleChildScrollView(
            child: Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                TextField(
                  controller: teamController,
                  decoration: const InputDecoration(
                    labelText: 'Team / Staff Name',
                    prefixIcon: Icon(Icons.person_rounded),
                  ),
                ),

                const SizedBox(height: 12),

                TextField(
                  controller: phoneController,
                  keyboardType: TextInputType.phone,
                  maxLength: 10,
                  inputFormatters: [
                    FilteringTextInputFormatter.digitsOnly,
                  ],
                  decoration: const InputDecoration(
                    labelText: 'Phone Number',
                    prefixText: '+91 ',
                    prefixIcon: Icon(Icons.phone_rounded),
                    counterText: '',
                  ),
                ),

                const SizedBox(height: 12),

                TextField(
                  controller: vehicleController,
                  decoration: const InputDecoration(
                    labelText: 'Vehicle Number',
                    prefixIcon:
                        Icon(Icons.directions_car_rounded),
                  ),
                ),

                const SizedBox(height: 12),

                TextField(
                  controller: driverController,
                  decoration: const InputDecoration(
                    labelText: 'Driver Name',
                    prefixIcon: Icon(Icons.badge_rounded),
                  ),
                ),
              ],
            ),
          ),
          actions: [
            TextButton(
              onPressed: () {
                Navigator.pop(context, false);
              },
              child: const Text('Cancel'),
            ),

            ElevatedButton(
              onPressed: () {
                if (teamController.text.trim().isEmpty ||
                    phoneController.text.length != 10 ||
                    vehicleController.text.trim().isEmpty ||
                    driverController.text.trim().isEmpty) {
                  ScaffoldMessenger.of(context).showSnackBar(
                    const SnackBar(
                      content: Text(
                        'Please complete all details correctly.',
                      ),
                    ),
                  );
                  return;
                }

                Navigator.pop(context, true);
              },
              style: ElevatedButton.styleFrom(
                backgroundColor: Colors.teal,
                foregroundColor: Colors.white,
              ),
              child: const Text('Save'),
            ),
          ],
        );
      },
    );

    if (result != true) return;

    final prefs = await SharedPreferences.getInstance();

    await prefs.setString(
      'ambulanceTeamName',
      teamController.text.trim(),
    );

    await prefs.setString(
      'ambulancePhone',
      phoneController.text.trim(),
    );

    await prefs.setString(
      'ambulanceNumber',
      vehicleController.text.trim(),
    );

    await prefs.setString(
      'ambulanceDriverName',
      driverController.text.trim(),
    );

    await loadAmbulanceDetails();

    if (!mounted) return;

    ScaffoldMessenger.of(context).showSnackBar(
      const SnackBar(
        content: Text(
          'Ambulance profile updated successfully.',
        ),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: const Color(0xFFF7FAFC),

      appBar: AppBar(
        backgroundColor: Colors.teal,
        foregroundColor: Colors.white,
        title: const Text(
          'Ambulance Profile',
          style: TextStyle(
            fontWeight: FontWeight.bold,
          ),
        ),
        centerTitle: true,
      ),

      body: SingleChildScrollView(
        padding: const EdgeInsets.all(20),
        child: Column(
          children: [
            const SizedBox(height: 10),

            // Profile icon
            Container(
              width: 100,
              height: 100,
              decoration: BoxDecoration(
                color: Colors.teal.withOpacity(0.10),
                shape: BoxShape.circle,
              ),
              child: const Icon(
                Icons.local_shipping_rounded,
                color: Colors.teal,
                size: 55,
              ),
            ),

            const SizedBox(height: 15),

            const Text(
              'Ambulance Account',
              style: TextStyle(
                fontSize: 24,
                fontWeight: FontWeight.bold,
                color: Color(0xFF202938),
              ),
            ),

            const SizedBox(height: 6),

            const Text(
              'Registered ambulance details',
              style: TextStyle(
                color: Colors.black54,
                fontSize: 14,
              ),
            ),

            const SizedBox(height: 30),

            _profileItem(
              Icons.person_rounded,
              'Team / Staff Name',
              teamName,
            ),

            const SizedBox(height: 12),

            _profileItem(
              Icons.phone_rounded,
              'Phone Number',
              phoneNumber,
            ),

            const SizedBox(height: 12),

            _profileItem(
              Icons.directions_car_rounded,
              'Vehicle Number',
              vehicleNumber,
            ),

            const SizedBox(height: 12),

            _profileItem(
              Icons.badge_rounded,
              'Driver Name',
              driverName,
            ),

            const SizedBox(height: 12),

            ValueListenableBuilder<String>(
              valueListenable: ambulanceStatus,
              builder: (context, status, child) {
                return _profileItem(
                  Icons.check_circle_rounded,
                  'Ambulance Status',
                  status,
                );
              },
            ),

            const SizedBox(height: 30),

            // EDIT PROFILE BUTTON
            SizedBox(
              width: double.infinity,
              child: ElevatedButton.icon(
                onPressed: editProfile,
                icon: const Icon(Icons.edit_rounded),
                label: const Text(
                  'Edit Profile',
                  style: TextStyle(
                    fontSize: 16,
                    fontWeight: FontWeight.bold,
                  ),
                ),
                style: ElevatedButton.styleFrom(
                  backgroundColor: Colors.teal,
                  foregroundColor: Colors.white,
                  padding: const EdgeInsets.symmetric(
                    vertical: 16,
                  ),
                  shape: RoundedRectangleBorder(
                    borderRadius:
                        BorderRadius.circular(15),
                  ),
                ),
              ),
            ),

            const SizedBox(height: 15),

            // LOGOUT BUTTON
            SizedBox(
              width: double.infinity,
              child: OutlinedButton.icon(
                onPressed: () async {
                  final shouldLogout =
                      await showDialog<bool>(
                    context: context,
                    builder: (context) {
                      return AlertDialog(
                        title: const Text('Logout'),
                        content: const Text(
                          'Are you sure you want to logout from the ambulance account?',
                        ),
                        actions: [
                          TextButton(
                            onPressed: () {
                              Navigator.pop(
                                context,
                                false,
                              );
                            },
                            child: const Text('Cancel'),
                          ),
                          ElevatedButton(
                            onPressed: () {
                              Navigator.pop(
                                context,
                                true,
                              );
                            },
                            style:
                                ElevatedButton.styleFrom(
                              backgroundColor: Colors.red,
                              foregroundColor:
                                  Colors.white,
                            ),
                            child: const Text('Logout'),
                          ),
                        ],
                      );
                    },
                  );

                  if (shouldLogout != true) return;

                  final prefs =
                      await SharedPreferences
                          .getInstance();

                  await prefs.setBool(
                    'ambulanceRegistered',
                    false,
                  );

                  if (!context.mounted) return;

                  Navigator.pushAndRemoveUntil(
                    context,
                    MaterialPageRoute(
                      builder: (context) =>
                          const AmbulanceRegistrationScreen(),
                    ),
                    (route) => false,
                  );
                },
                icon: const Icon(
                  Icons.logout_rounded,
                ),
                label: const Text(
                  'Logout',
                  style: TextStyle(
                    fontSize: 16,
                    fontWeight: FontWeight.bold,
                  ),
                ),
                style: OutlinedButton.styleFrom(
                  foregroundColor: Colors.red,
                  side: const BorderSide(
                    color: Colors.red,
                  ),
                  padding: const EdgeInsets.symmetric(
                    vertical: 16,
                  ),
                  shape: RoundedRectangleBorder(
                    borderRadius:
                        BorderRadius.circular(15),
                  ),
                ),
              ),
            ),
          ],
        ),
      ),
    );
  }

  Widget _profileItem(
    IconData icon,
    String title,
    String value,
  ) {
    return Container(
      width: double.infinity,
      padding: const EdgeInsets.all(18),
      decoration: BoxDecoration(
        color: Colors.white,
        borderRadius: BorderRadius.circular(17),
        border: Border.all(
          color: Colors.grey.shade200,
        ),
      ),
      child: Row(
        children: [
          Container(
            width: 48,
            height: 48,
            decoration: BoxDecoration(
              color: Colors.teal.withOpacity(0.08),
              shape: BoxShape.circle,
            ),
            child: Icon(
              icon,
              color: Colors.teal,
              size: 25,
            ),
          ),

          const SizedBox(width: 15),

          Expanded(
            child: Column(
              crossAxisAlignment:
                  CrossAxisAlignment.start,
              children: [
                Text(
                  title,
                  style: const TextStyle(
                    fontSize: 13,
                    color: Colors.black54,
                  ),
                ),

                const SizedBox(height: 5),

                Text(
                  value,
                  style: const TextStyle(
                    fontSize: 16,
                    fontWeight: FontWeight.bold,
                  ),
                ),
              ],
            ),
          ),
        ],
      ),
    );
  }
}
