class DoctorRegistrationScreen extends StatefulWidget {
  const DoctorRegistrationScreen({super.key});

  @override
  State<DoctorRegistrationScreen> createState() =>
      _DoctorRegistrationScreenState();
}

class _DoctorRegistrationScreenState
    extends State<DoctorRegistrationScreen> {
  final TextEditingController nameController = TextEditingController();
  final TextEditingController phoneController = TextEditingController();
  final TextEditingController otpController = TextEditingController();
  final TextEditingController registrationNumberController =
      TextEditingController();
  final TextEditingController qualificationController =
      TextEditingController();
  final TextEditingController specializationController =
      TextEditingController();
  final TextEditingController experienceController =
      TextEditingController();
  final TextEditingController hospitalController =
      TextEditingController();

  bool otpSent = false;
  bool otpVerified = false;

  @override
  void dispose() {
    nameController.dispose();
    phoneController.dispose();
    otpController.dispose();
    registrationNumberController.dispose();
    qualificationController.dispose();
    specializationController.dispose();
    experienceController.dispose();
    hospitalController.dispose();
    super.dispose();
  }

  void sendOTP() {
    if (phoneController.text.trim().length != 10) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('Please enter a valid 10-digit phone number.'),
        ),
      );
      return;
    }

    setState(() {
      otpSent = true;
    });

    ScaffoldMessenger.of(context).showSnackBar(
      const SnackBar(
        content: Text('OTP sent! Test OTP: 123456'),
      ),
    );
  }

  void verifyOTP() {
    if (!otpSent) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('Please send OTP first.'),
        ),
      );
      return;
    }

    if (otpController.text.trim() == '123456') {
      setState(() {
        otpVerified = true;
      });

      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('Phone number verified successfully.'),
        ),
      );
    } else {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('Invalid OTP. Please try again.'),
        ),
      );
    }
  }

  void registerDoctor() {
    if (nameController.text.trim().isEmpty ||
        phoneController.text.trim().isEmpty ||
        registrationNumberController.text.trim().isEmpty ||
        qualificationController.text.trim().isEmpty ||
        specializationController.text.trim().isEmpty ||
        experienceController.text.trim().isEmpty ||
        hospitalController.text.trim().isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('Please fill in all required fields.'),
        ),
      );
      return;
    }

    if (!otpVerified) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('Please verify your phone number first.'),
        ),
      );
      return;
    }

       Navigator.pushReplacement(
        context,
         MaterialPageRoute(
        builder: (context) => const DoctorKycScreen(),
        ),
      );
    }

  Widget inputField({
    required String label,
    required TextEditingController controller,
    TextInputType keyboardType = TextInputType.text,
    String? hintText,
  }) {
    return Padding(
      padding: const EdgeInsets.only(bottom: 16),
      child: TextField(
        controller: controller,
        keyboardType: keyboardType,
        decoration: InputDecoration(
          labelText: label,
          hintText: hintText,
          prefixText:
              keyboardType == TextInputType.phone ? '+91 ' : null,
          border: OutlineInputBorder(
            borderRadius: BorderRadius.circular(12),
          ),
        ),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: const Text('Doctor Registration'),
        backgroundColor: const Color(0xFF3F6FA8),
        foregroundColor: Colors.white,
      ),
      body: SingleChildScrollView(
        padding: const EdgeInsets.all(20),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            const Icon(
              Icons.medical_services,
              size: 60,
              color: Color(0xFF3F6FA8),
            ),

            const SizedBox(height: 12),

            const Text(
              'Doctor Registration',
              style: TextStyle(
                fontSize: 25,
                fontWeight: FontWeight.bold,
              ),
            ),

            const SizedBox(height: 6),

            const Text(
              'Create your doctor account to access the Doctor Portal.',
              style: TextStyle(
                color: Colors.grey,
                fontSize: 14,
              ),
            ),

            const SizedBox(height: 25),

            const Text(
              'Doctor Details',
              style: TextStyle(
                fontSize: 18,
                fontWeight: FontWeight.bold,
              ),
            ),

            const SizedBox(height: 15),

            inputField(
              label: 'Full Name',
              controller: nameController,
              hintText: 'Enter doctor name',
            ),

            inputField(
              label: 'Medical Registration Number',
              controller: registrationNumberController,
              hintText: 'Enter medical registration number',
            ),

            inputField(
              label: 'Qualification',
              controller: qualificationController,
              hintText: 'Example: MBBS, MD',
            ),

            inputField(
              label: 'Specialization',
              controller: specializationController,
              hintText: 'Example: General Medicine',
            ),

            inputField(
              label: 'Years of Experience',
              controller: experienceController,
              keyboardType: TextInputType.number,
              hintText: 'Enter years of experience',
            ),

            inputField(
              label: 'Hospital / Clinic',
              controller: hospitalController,
              hintText: 'Enter hospital or clinic name',
            ),

            const SizedBox(height: 5),

            const Text(
              'Phone Verification',
              style: TextStyle(
                fontSize: 18,
                fontWeight: FontWeight.bold,
              ),
            ),

            const SizedBox(height: 15),

            Row(
              children: [
                Expanded(
                  child: TextField(
                    controller: phoneController,
                    keyboardType: TextInputType.phone,
                    maxLength: 10,
                    decoration: InputDecoration(
                      labelText: 'Phone Number',
                      prefixText: '+91 ',
                      counterText: '',
                      border: OutlineInputBorder(
                        borderRadius: BorderRadius.circular(12),
                      ),
                    ),
                  ),
                ),

                const SizedBox(width: 10),

                SizedBox(
                  height: 55,
                  child: ElevatedButton(
                    onPressed: sendOTP,
                    child: const Text('Send OTP'),
                  ),
                ),
              ],
            ),

            const SizedBox(height: 16),

            if (otpSent) ...[
              TextField(
                controller: otpController,
                keyboardType: TextInputType.number,
                maxLength: 6,
                decoration: InputDecoration(
                  labelText: 'Enter OTP',
                  counterText: '',
                  border: OutlineInputBorder(
                    borderRadius: BorderRadius.circular(12),
                  ),
                ),
              ),

              const SizedBox(height: 12),

              SizedBox(
                width: double.infinity,
                height: 50,
                child: OutlinedButton(
                  onPressed: verifyOTP,
                  child: Text(
                    otpVerified
                        ? 'Phone Verified ✓'
                        : 'Verify OTP',
                  ),
                ),
              ),

              const SizedBox(height: 20),
            ],

            SizedBox(
              width: double.infinity,
              height: 55,
              child: ElevatedButton.icon(
                onPressed: registerDoctor,
                icon: const Icon(Icons.person_add),
                label: const Text(
                  'Register as Doctor',
                  style: TextStyle(fontSize: 16),
                ),
              ),
            ),

            const SizedBox(height: 20),

            const Center(
              child: Text(
                'Doctor registration is subject to verification.',
                textAlign: TextAlign.center,
                style: TextStyle(
                  color: Colors.grey,
                  fontSize: 12,
                ),
              ),
            ),
          ],
        ),
      ),
    );
  }
}


