class DoctorKycScreen extends StatefulWidget {
  const DoctorKycScreen({super.key});

  @override
  State<DoctorKycScreen> createState() => _DoctorKycScreenState();
}

class _DoctorKycScreenState extends State<DoctorKycScreen> {
  bool registrationCertificateUploaded = false;
  bool qualificationCertificateUploaded = false;
  bool identityProofUploaded = false;
  bool profilePhotoUploaded = false;
  bool declarationAccepted = false;

  void uploadDocument(String documentName, VoidCallback onUploaded) {
    showModalBottomSheet(
      context: context,
      builder: (context) {
        return SafeArea(
          child: Padding(
            padding: const EdgeInsets.all(20),
            child: Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                Text(
                  'Upload $documentName',
                  style: const TextStyle(
                    fontSize: 18,
                    fontWeight: FontWeight.bold,
                  ),
                ),
                const SizedBox(height: 20),
                ListTile(
                  leading: const Icon(Icons.camera_alt),
                  title: const Text('Take Photo'),
                  onTap: () {
                    Navigator.pop(context);
                    onUploaded();
                  },
                ),
                ListTile(
                  leading: const Icon(Icons.folder),
                  title: const Text('Choose from Files'),
                  onTap: () {
                    Navigator.pop(context);
                    onUploaded();
                  },
                ),
              ],
            ),
          ),
        );
      },
    );
  }

  void submitKyc() {
    if (!registrationCertificateUploaded ||
        !qualificationCertificateUploaded ||
        !identityProofUploaded ||
        !profilePhotoUploaded) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('Please upload all required KYC documents.'),
        ),
      );
      return;
    }

    if (!declarationAccepted) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('Please accept the declaration.'),
        ),
      );
      return;
    }

    showDialog(
      context: context,
      barrierDismissible: false,
      builder: (context) {
        return AlertDialog(
          title: const Text('KYC Submitted'),
          content: const Text(
            'Your KYC documents have been submitted successfully. '
            'Your account is now under verification.',
          ),
          actions: [
            TextButton(
              onPressed: () {
                Navigator.pop(context);

                Navigator.pushReplacement(
                  context,
                  MaterialPageRoute(
                    builder: (context) => const DoctorLoginScreen(),
                  ),
                );
              },
              child: const Text('Continue'),
            ),
          ],
        );
      },
    );
  }

  Widget documentTile({
    required String title,
    required bool uploaded,
    required VoidCallback onTap,
  }) {
    return Container(
      margin: const EdgeInsets.only(bottom: 12),
      decoration: BoxDecoration(
        color: Colors.white,
        borderRadius: BorderRadius.circular(14),
        border: Border.all(
          color: uploaded
              ? Colors.green.shade300
              : const Color(0xFFDCE5EE),
        ),
      ),
      child: ListTile(
        leading: CircleAvatar(
          backgroundColor: uploaded
              ? Colors.green.shade50
              : const Color(0xFFEAF2FA),
          child: Icon(
            uploaded ? Icons.check : Icons.upload_file,
            color: uploaded
                ? Colors.green
                : const Color(0xFF3F6FA8),
          ),
        ),
        title: Text(
          title,
          style: const TextStyle(
            fontWeight: FontWeight.w600,
            color: Color(0xFF26384A),
          ),
        ),
        subtitle: Text(
          uploaded ? 'Document uploaded' : 'Required',
          style: TextStyle(
            color: uploaded ? Colors.green : Colors.grey,
            fontSize: 12,
          ),
        ),
        trailing: TextButton(
          onPressed: onTap,
          child: Text(
            uploaded ? 'Change' : 'Upload',
          ),
        ),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: const Color(0xFFF7FAFC),

      appBar: AppBar(
        title: const Text('Doctor KYC Verification'),
        backgroundColor: const Color(0xFF3F6FA8),
        foregroundColor: Colors.white,
        elevation: 0,
      ),

      body: SingleChildScrollView(
        padding: const EdgeInsets.all(20),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            // Header
            const Text(
              'Verify Your Medical Identity',
              style: TextStyle(
                fontSize: 24,
                fontWeight: FontWeight.bold,
                color: Color(0xFF26384A),
              ),
            ),

            const SizedBox(height: 8),

            const Text(
              'Please upload the required documents to verify '
              'your doctor account.',
              style: TextStyle(
                fontSize: 14,
                color: Colors.grey,
                height: 1.5,
              ),
            ),

            const SizedBox(height: 20),

            // KYC Status
            Container(
              padding: const EdgeInsets.all(16),
              decoration: BoxDecoration(
                color: const Color(0xFFFFF7E6),
                borderRadius: BorderRadius.circular(14),
                border: Border.all(
                  color: const Color(0xFFFFD98A),
                ),
              ),
              child: const Row(
                children: [
                  Icon(
                    Icons.pending_actions,
                    color: Colors.orange,
                  ),
                  SizedBox(width: 12),
                  Expanded(
                    child: Text(
                      'KYC Status: Pending Verification',
