                fontSize: 18,
                fontWeight: FontWeight.bold,
                color: Color(0xFF26384A),
              ),
            ),

            const SizedBox(height: 8),

            const Text(
              'Upload clear and readable documents for verification.',
              style: TextStyle(
                fontSize: 13,
                color: Colors.grey,
              ),
            ),

            const SizedBox(height: 14),

            // Medical Registration Certificate
            documentTile(
              title: 'Medical Registration Certificate',
              uploaded: registrationCertificateUploaded,
              onTap: () {
                uploadDocument(
                  'Medical Registration Certificate',
                  () {
                    setState(() {
                      registrationCertificateUploaded = true;
                    });
                  },
                );
              },
            ),

            // Qualification Certificate
            documentTile(
              title: 'Qualification Certificate',
              uploaded: qualificationCertificateUploaded,
              onTap: () {
                uploadDocument(
                  'Qualification Certificate',
                  () {
                    setState(() {
                      qualificationCertificateUploaded = true;
                    });
                  },
                );
              },
            ),

            // Identity Proof
            documentTile(
              title: 'Identity Proof',
              uploaded: identityProofUploaded,
              onTap: () {
                uploadDocument(
                  'Identity Proof',
                  () {
                    setState(() {
                      identityProofUploaded = true;
                    });
                  },
                );
              },
            ),

            // Profile Photo
            documentTile(
              title: 'Profile Photo',
