class DoctorLoginScreen extends StatefulWidget {
  const DoctorLoginScreen({super.key});

  @override
  State<DoctorLoginScreen> createState() => _DoctorLoginScreenState();
}

class _DoctorLoginScreenState extends State<DoctorLoginScreen> {
  final TextEditingController phoneController = TextEditingController();
  final TextEditingController otpController = TextEditingController();

  bool otpSent = false;
  bool otpVerified = false;

  @override
  void dispose() {
    phoneController.dispose();
    otpController.dispose();
    super.dispose();
  }

  void sendOTP() {
    if (phoneController.text.trim().length != 10) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('Please enter a valid 10-digit phone number.'),
        ),
      );
      return;
    }

    setState(() {
      otpSent = true;
    });

    ScaffoldMessenger.of(context).showSnackBar(
      const SnackBar(
        content: Text('OTP sent! Test OTP: 123456'),
      ),
    );
  }

  void verifyOTP() {
    if (otpController.text.trim() == '123456') {
      setState(() {
        otpVerified = true;
      });

      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('OTP verified successfully.'),
        ),
      );
    } else {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('Invalid OTP. Please try again.'),
        ),
      );
    }
  }

  void loginDoctor() {
    if (!otpVerified) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('Please verify your phone number first.'),
        ),
      );
      return;
    }

    Navigator.pushReplacement(
      context,
      MaterialPageRoute(
        builder: (context) => const DoctorDashboardScreen(),
      ),
    );
  }

  Widget inputField({
    required String label,
    required String hint,
    required IconData icon,
    required TextEditingController controller,
    TextInputType? keyboardType,
    int? maxLength,
    Widget? suffixIcon,
  }) {
    return TextField(
      controller: controller,
      keyboardType: keyboardType,
      maxLength: maxLength,
      decoration: InputDecoration(
        labelText: label,
        hintText: hint,
        prefixIcon: Icon(icon),
        suffixIcon: suffixIcon,
        counterText: '',
        filled: true,
        fillColor: Colors.white,
        border: OutlineInputBorder(
          borderRadius: BorderRadius.circular(14),
          borderSide: BorderSide.none,
        ),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: const Color(0xFFF7FAFC),

      appBar: AppBar(
        title: const Text('Doctor Login'),
        backgroundColor: const Color(0xFF3F6FA8),
        foregroundColor: Colors.white,
        elevation: 0,
      ),

      body: SingleChildScrollView(
        padding: const EdgeInsets.all(20),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [

            const SizedBox(height: 20),

            Center(
              child: CircleAvatar(
                radius: 42,
                backgroundColor: const Color(0xFFEAF2FA),
                child: Icon(
                  Icons.medical_services_outlined,
                  size: 42,
                  color: const Color(0xFF3F6FA8),
                ),
              ),
            ),

            const SizedBox(height: 20),

            const Center(
              child: Text(
                'Welcome, Doctor',
                style: TextStyle(
                  fontSize: 25,
                  fontWeight: FontWeight.bold,
                  color: Color(0xFF26384A),
                ),
              ),
            ),

            const SizedBox(height: 8),

            const Center(
              child: Text(
                'Login to access your Doctor Portal',
                textAlign: TextAlign.center,
                style: TextStyle(
                  fontSize: 14,
                  color: Colors.grey,
                ),
              ),
            ),

            const SizedBox(height: 30),

            inputField(
              label: 'Phone Number',
              hint: 'Enter your 10-digit phone number',
              icon: Icons.phone_outlined,
              controller: phoneController,
              keyboardType: TextInputType.phone,
              maxLength: 10,
              suffixIcon: IconButton(
                icon: const Icon(Icons.send),
                onPressed: sendOTP,
              ),
            ),

            const SizedBox(height: 18),

            if (otpSent) ...[
              inputField(
                label: 'OTP',
                hint: 'Enter 6-digit OTP',
                icon: Icons.lock_outline,
                controller: otpController,
                keyboardType: TextInputType.number,
                maxLength: 6,
                suffixIcon: IconButton(
                  icon: Icon(
                    otpVerified
                        ? Icons.check_circle
                        : Icons.verified_outlined,
                    color: otpVerified ? Colors.green : null,
                  ),
                  onPressed: otpVerified ? null : verifyOTP,
                ),
              ),

              const SizedBox(height: 8),

              Text(
                otpVerified
                    ? 'Phone number verified'
                    : 'Test OTP: 123456',
                style: TextStyle(
                  fontSize: 13,
                  color: otpVerified ? Colors.green : Colors.grey,
                ),
              ),

              const SizedBox(height: 24),
            ],

            SizedBox(
              width: double.infinity,
              height: 52,
              child: ElevatedButton(
                onPressed: loginDoctor,
                style: ElevatedButton.styleFrom(
                  backgroundColor: const Color(0xFF3F6FA8),
                  foregroundColor: Colors.white,
                  shape: RoundedRectangleBorder(
                    borderRadius: BorderRadius.circular(14),
                  ),
                ),
                child: const Text(
                  'Login',
                  style: TextStyle(
                    fontSize: 16,
                    fontWeight: FontWeight.bold,
                  ),
                ),
              ),
            ),

            const SizedBox(height: 20),

            const Center(
              child: Text(
                'Doctor accounts are subject to verification.',
                textAlign: TextAlign.center,
                style: TextStyle(
                  fontSize: 12,
                  color: Colors.grey,
                ),
              ),
            ),
          ],
        ),
      ),
    );
  }
}

