class DoctorAvailabilityScreen extends StatefulWidget {
  const DoctorAvailabilityScreen({super.key});

  @override
  State<DoctorAvailabilityScreen> createState() =>
      _DoctorAvailabilityScreenState();
}

class _DoctorAvailabilityScreenState
    extends State<DoctorAvailabilityScreen> {
  bool isAvailable = true;

  final List<String> days = [
    'Monday',
    'Tuesday',
    'Wednesday',
    'Thursday',
    'Friday',
    'Saturday',
    'Sunday',
  ];

  final Set<String> selectedDays = {
    'Monday',
    'Tuesday',
    'Wednesday',
    'Thursday',
    'Friday',
  };

  TimeOfDay startTime = const TimeOfDay(hour: 9, minute: 0);
  TimeOfDay endTime = const TimeOfDay(hour: 17, minute: 0);

  String slotDuration = '30 minutes';

  final List<DateTime> unavailableDates = [];

  Future<void> selectStartTime() async {
    final TimeOfDay? picked = await showTimePicker(
      context: context,
      initialTime: startTime,
    );

    if (picked != null) {
      setState(() {
        startTime = picked;
      });
    }
  }

  Future<void> selectEndTime() async {
    final TimeOfDay? picked = await showTimePicker(
      context: context,
      initialTime: endTime,
    );

    if (picked != null) {
      setState(() {
        endTime = picked;
      });
    }
  }

  Future<void> addUnavailableDate() async {
    final DateTime? picked = await showDatePicker(
      context: context,
      initialDate: DateTime.now(),
      firstDate: DateTime.now(),
      lastDate: DateTime(2035),
    );

    if (picked != null) {
      setState(() {
        final alreadyAdded = unavailableDates.any(
          (date) =>
              date.year == picked.year &&
              date.month == picked.month &&
              date.day == picked.day,
        );

        if (!alreadyAdded) {
          unavailableDates.add(picked);
        }
      });
    }
  }

  String formatTime(TimeOfDay time) {
    return time.format(context);
  }

  String formatDate(DateTime date) {
    return '${date.day}/${date.month}/${date.year}';
  }

  void saveAvailability() {
    if (isAvailable && selectedDays.isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('Please select at least one working day.'),
        ),
      );
      return;
    }

    ScaffoldMessenger.of(context).showSnackBar(
      const SnackBar(
        content: Text('Doctor availability saved successfully.'),
      ),
    );
  }

  Widget sectionTitle(String title) {
    return Padding(
      padding: const EdgeInsets.only(bottom: 12),
      child: Text(
        title,
        style: const TextStyle(
          fontSize: 18,
          fontWeight: FontWeight.bold,
        ),
      ),
    );
  }

  Widget settingCard({
    required Widget child,
  }) {
    return Card(
      elevation: 1,
      margin: const EdgeInsets.only(bottom: 20),
      shape: RoundedRectangleBorder(
        borderRadius: BorderRadius.circular(16),
      ),
      child: Padding(
        padding: const EdgeInsets.all(16),
        child: child,
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: const Text('Doctor Availability'),
        backgroundColor: const Color(0xFF3F6FA8),
        foregroundColor: Colors.white,
      ),

      body: SingleChildScrollView(
        padding: const EdgeInsets.all(20),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [

            // ------------------------------------------------
            // STATUS
            // ------------------------------------------------

            sectionTitle('Availability Status'),

            settingCard(
              child: SwitchListTile(
                contentPadding: EdgeInsets.zero,
                title: const Text(
                  'Available for Consultation',
                  style: TextStyle(
                    fontWeight: FontWeight.bold,
                  ),
                ),
                subtitle: Text(
                  isAvailable
                      ? 'Patients can book appointments with you.'
                      : 'Patients cannot book appointments with you.',
                ),
                value: isAvailable,
                activeColor: Colors.green,
                onChanged: (value) {
                  setState(() {
                    isAvailable = value;
                  });
                },
              ),
            ),

            // ------------------------------------------------
            // WORKING DAYS
            // ------------------------------------------------

            sectionTitle('Working Days'),

            settingCard(
              child: Column(
                children: days.map((day) {
                  return CheckboxListTile(
                    contentPadding: EdgeInsets.zero,
                    title: Text(day),
                    value: selectedDays.contains(day),
                    activeColor: const Color(0xFF3F6FA8),
                    onChanged: isAvailable
                        ? (value) {
                            setState(() {
                              if (value == true) {
                                selectedDays.add(day);
                              } else {
                                selectedDays.remove(day);
                              }
                            });
                          }
                        : null,
                  );
                }).toList(),
              ),
            ),

            // ------------------------------------------------
            // CONSULTATION HOURS
            // ------------------------------------------------

            sectionTitle('Consultation Hours'),

            settingCard(
              child: Column(
                children: [

                  ListTile(
                    contentPadding: EdgeInsets.zero,
                    leading: const Icon(
                      Icons.login,
                      color: Color(0xFF3F6FA8),
                    ),
                    title: const Text('Start Time'),
                    subtitle: Text(formatTime(startTime)),
                    trailing: const Icon(
                      Icons.arrow_forward_ios,
                      size: 16,
                    ),
                    onTap: isAvailable
                        ? selectStartTime
                        : null,
                  ),

                  const Divider(),

                  ListTile(
                    contentPadding: EdgeInsets.zero,
                    leading: const Icon(
                      Icons.logout,
                      color: Color(0xFF3F6FA8),
                    ),
                    title: const Text('End Time'),
                    subtitle: Text(formatTime(endTime)),
                    trailing: const Icon(
                      Icons.arrow_forward_ios,
                      size: 16,
                    ),
                    onTap: isAvailable
                        ? selectEndTime
                        : null,
                  ),
                ],
              ),
            ),

            // ------------------------------------------------
            // SLOT DURATION
            // ------------------------------------------------

            sectionTitle('Appointment Slot Duration'),

            settingCard(
              child: DropdownButtonFormField<String>(
                value: slotDuration,
                decoration: InputDecoration(
                  labelText: 'Slot Duration',
                  border: OutlineInputBorder(
                    borderRadius: BorderRadius.circular(12),
                  ),
                ),
                items: const [
                  DropdownMenuItem(
                    value: '15 minutes',
                    child: Text('15 minutes'),
                  ),
                  DropdownMenuItem(
                    value: '30 minutes',
                    child: Text('30 minutes'),
                  ),
                  DropdownMenuItem(
                    value: '45 minutes',
                    child: Text('45 minutes'),
                  ),
                  DropdownMenuItem(
                    value: '60 minutes',
                    child: Text('60 minutes'),
                  ),
                ],
                onChanged: isAvailable
                    ? (value) {
                        if (value != null) {
                          setState(() {
                            slotDuration = value;
                          });
                        }
                      }
                    : null,
              ),
            ),

            // ------------------------------------------------
            // UNAVAILABLE / LEAVE DATES
            // ------------------------------------------------

            sectionTitle('Leave / Unavailable Dates'),

            settingCard(
              child: Column(
                children: [

                  SizedBox(
                    width: double.infinity,
                    child: OutlinedButton.icon(
                      onPressed:
                          isAvailable ? addUnavailableDate : null,
                      icon: const Icon(Icons.add),
                      label: const Text(
                        'Add Unavailable Date',
                      ),
                    ),
                  ),

                  if (unavailableDates.isNotEmpty) ...[
                    const SizedBox(height: 15),

                    ...unavailableDates.map(
                      (date) {
                        return ListTile(
                          contentPadding: EdgeInsets.zero,
                          leading: const Icon(
                            Icons.event_busy,
                            color: Colors.red,
                          ),
                          title: Text(
                            formatDate(date),
                          ),
                          subtitle: const Text(
                            'Doctor unavailable',
                          ),
                          trailing: IconButton(
                            icon: const Icon(
                              Icons.delete_outline,
                              color: Colors.red,
                            ),
                            onPressed: () {
                              setState(() {
                                unavailableDates.remove(date);
                              });
                            },
                          ),
                        );
                      },
                    ),
                  ],
                ],
              ),
            ),

            // ------------------------------------------------
            // SAVE
            // ------------------------------------------------

            SizedBox(
              width: double.infinity,
              height: 55,
              child: ElevatedButton.icon(
                onPressed: saveAvailability,
                icon: const Icon(Icons.save),
                label: const Text(
                  'Save Availability',
                  style: TextStyle(fontSize: 16),
                ),
                style: ElevatedButton.styleFrom(
                  backgroundColor: const Color(0xFF3F6FA8),
                  foregroundColor: Colors.white,
                  shape: RoundedRectangleBorder(
                    borderRadius: BorderRadius.circular(14),
                  ),
                ),
              ),
            ),

            const SizedBox(height: 20),
          ],
        ),
      ),
    );
  }
}
