class DoctorAppointmentsScreen extends StatefulWidget {
  const DoctorAppointmentsScreen({super.key});

  @override
  State<DoctorAppointmentsScreen> createState() =>
      _DoctorAppointmentsScreenState();
}

class _DoctorAppointmentsScreenState
    extends State<DoctorAppointmentsScreen> {

  // ----------------------------------------------------------
  // DEMO APPOINTMENTS
  // These represent the APPOINTMENTS entity from the ER diagram.
  // Backend/database will replace this later.
  // ----------------------------------------------------------

  final List<Map<String, String>> appointments = [
    {
      'patientName': 'Anjali Kumar',
      'date': '20/09/2026',
      'startTime': '10:00 AM',
      'endTime': '10:30 AM',
      'mode': 'Online',
      'status': 'Pending',
      'reason': 'Fever and headache',
    },
    {
      'patientName': 'Rahul Thomas',
      'date': '20/09/2026',
      'startTime': '11:00 AM',
      'endTime': '11:30 AM',
      'mode': 'Offline',
      'status': 'Accepted',
      'reason': 'General consultation',
    },
    {
      'patientName': 'Meera Das',
      'date': '21/09/2026',
      'startTime': '02:00 PM',
      'endTime': '02:30 PM',
      'mode': 'Online',
      'status': 'Pending',
      'reason': 'Cough and cold',
    },
  ];

  // ----------------------------------------------------------
  // STATUS UPDATE
  // ----------------------------------------------------------

  void updateStatus(int index, String status) {
    setState(() {
      appointments[index]['status'] = status;
    });

    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text(
          status == 'Accepted'
              ? 'Appointment accepted successfully.'
              : 'Appointment declined.',
        ),
      ),
    );
  }

  // ----------------------------------------------------------
  // APPOINTMENT DETAILS
  // ----------------------------------------------------------

  void showAppointmentDetails(Map<String, dynamic> appointment) {
  showModalBottomSheet(
    context: context,
    isScrollControlled: true,
    shape: const RoundedRectangleBorder(
      borderRadius: BorderRadius.vertical(
        top: Radius.circular(22),
      ),
    ),
    builder: (context) {
      return Padding(
        padding: const EdgeInsets.fromLTRB(
          20,
          20,
          20,
          30,
        ),
        child: SingleChildScrollView(
          child: Column(
            mainAxisSize: MainAxisSize.min,
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [

              // Header
              Row(
                children: [
                  const CircleAvatar(
                    radius: 28,
                    backgroundColor: Color(0xFFEAF2FA),
                    child: Icon(
                      Icons.person,
                      color: Color(0xFF3F6FA8),
                      size: 30,
                    ),
                  ),

                  const SizedBox(width: 14),

                  Expanded(
                    child: Text(
                      appointment['doctor']?.toString() ??
                          'Doctor',
                      style: const TextStyle(
                        fontSize: 20,
                        fontWeight: FontWeight.bold,
                      ),
                    ),
                  ),
                ],
              ),

              const SizedBox(height: 20),

              appointmentDetailRow(
                Icons.medical_services_outlined,
                'Specialization',
                appointment['specialty']?.toString() ??
                    'Not available',
              ),

              appointmentDetailRow(
                Icons.school_outlined,
                'Qualification',
                appointment['qualification']?.toString() ??
                    'Not available',
              ),

              appointmentDetailRow(
                Icons.work_outline,
                'Experience',
                '${appointment['experience_years'] ?? 0} years',
              ),

              appointmentDetailRow(
                Icons.calendar_today,
                'Appointment Date',
                appointment['date']?.toString() ??
                    'Not available',
              ),

              appointmentDetailRow(
                Icons.access_time,
                'Start Time',
                appointment['time']?.toString() ??
                    'Not available',
              ),

              appointmentDetailRow(
                Icons.access_time_filled,
                'End Time',
                appointment['end_time']?.toString() ??
                    'Not available',
              ),

              appointmentDetailRow(
                Icons.video_call,
                'Consultation Mode',
                appointment['consultation_mode']?.toString() ??
                    'Not available',
              ),

              appointmentDetailRow(
                Icons.info_outline,
                'Status',
                appointment['status']?.toString() ??
                    'Not available',
              ),

              appointmentDetailRow(
                Icons.description_outlined,
                'Reason for Visit',
                appointment['reason_for_visit']?.toString() ??
                    'Not provided',
              ),

              const SizedBox(height: 10),

              // Close button
              SizedBox(
                width: double.infinity,
                child: ElevatedButton(
                  onPressed: () {
                    Navigator.pop(context);
                  },
                  style: ElevatedButton.styleFrom(
                    backgroundColor: const Color(0xFF3F6FA8),
                    foregroundColor: Colors.white,
                    minimumSize: const Size(
                      double.infinity,
                      48,
                    ),
                    elevation: 0,
                    shape: RoundedRectangleBorder(
                      borderRadius: BorderRadius.circular(14),
                    ),
                  ),
                  child: Text(
                    tr('Close', selectedLanguage),
                    style: const TextStyle(
                      fontWeight: FontWeight.w600,
                    ),
                  ),
                ),
              ),
            ],
          ),
        ),
      );
    },
  );
}

  // ----------------------------------------------------------
  // APPOINTMENT DETAIL ROW
  // ----------------------------------------------------------

  Widget appointmentDetailRow(
    IconData icon,
    String title,
    String value,
  ) {
    return Padding(
      padding: const EdgeInsets.only(bottom: 14),
      child: Row(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [

          Icon(
            icon,
            size: 21,
            color: const Color(0xFF3F6FA8),
          ),

          const SizedBox(width: 12),

          Expanded(
            child: Column(
              crossAxisAlignment:
                  CrossAxisAlignment.start,
              children: [
                Text(
                  title,
                  style: const TextStyle(
                    fontSize: 12,
                    color: Colors.grey,
                  ),
                ),

                const SizedBox(height: 2),

                Text(
                  value,
                  style: const TextStyle(
                    fontSize: 15,
                    fontWeight: FontWeight.w500,
                  ),
                ),
              ],
            ),
          ),
        ],
      ),
    );
  }

  // ----------------------------------------------------------
  // APPOINTMENT CARD
  // ----------------------------------------------------------

  Widget appointmentCard(int index) {
    final appointment = appointments[index];

    final status = appointment['status']!;

    return Card(
      elevation: 2,
      margin: const EdgeInsets.only(bottom: 16),
      shape: RoundedRectangleBorder(
        borderRadius: BorderRadius.circular(16),
      ),
      child: Padding(
        padding: const EdgeInsets.all(17),
        child: Column(
          crossAxisAlignment:
              CrossAxisAlignment.start,
          children: [

            // Patient
            Row(
              children: [

                const CircleAvatar(
                  radius: 25,
                  backgroundColor: Color(0xFFEAF2FA),
                  child: Icon(
                    Icons.person,
                    color: Color(0xFF3F6FA8),
                  ),
                ),

                const SizedBox(width: 12),

                Expanded(
                  child: Column(
                    crossAxisAlignment:
                        CrossAxisAlignment.start,
                    children: [

                      Text(
                        appointment['patientName']!,
                        style: const TextStyle(
                          fontSize: 17,
                          fontWeight: FontWeight.bold,
                        ),
                      ),

                      const SizedBox(height: 4),

                      Text(
                        appointment['reason']!,
                        style: const TextStyle(
                          fontSize: 13,
                          color: Colors.grey,
                        ),
                      ),
                    ],
                  ),
                ),

                Container(
                  padding: const EdgeInsets.symmetric(
                    horizontal: 10,
                    vertical: 6,
                  ),
                  decoration: BoxDecoration(
                    color: status == 'Accepted'
                        ? Colors.green.withOpacity(0.12)
                        : status == 'Declined'
                            ? Colors.red.withOpacity(0.12)
                            : Colors.orange.withOpacity(0.12),
                    borderRadius:
                        BorderRadius.circular(20),
                  ),
                  child: Text(
                    status,
                    style: TextStyle(
                      fontSize: 12,
                      fontWeight: FontWeight.bold,
                      color: status == 'Accepted'
                          ? Colors.green
                          : status == 'Declined'
                              ? Colors.red
                              : Colors.orange,
                    ),
                  ),
                ),
              ],
            ),

            const SizedBox(height: 16),

            const Divider(),

            const SizedBox(height: 10),

            // Date
            Row(
              children: [

                const Icon(
                  Icons.calendar_today,
                  size: 18,
                  color: Color(0xFF3F6FA8),
                ),

                const SizedBox(width: 8),

                Text(
                  appointment['date']!,
                  style: const TextStyle(
                    fontSize: 14,
                  ),
                ),

                const SizedBox(width: 20),

                const Icon(
                  Icons.access_time,
                  size: 18,
                  color: Color(0xFF3F6FA8),
                ),

                const SizedBox(width: 8),

                Expanded(
                  child: Text(
                    '${appointment['startTime']} - ${appointment['endTime']}',
                    style: const TextStyle(
                      fontSize: 14,
                    ),
                  ),
                ),
              ],
            ),

            const SizedBox(height: 12),

            // Consultation mode
            Row(
              children: [

                Icon(
                  appointment['mode'] == 'Online'
                      ? Icons.video_call
                      : Icons.local_hospital,
                  size: 19,
                  color: const Color(0xFF3F6FA8),
                ),

                const SizedBox(width: 8),

                Text(
                  appointment['mode']!,
                  style: const TextStyle(
                    fontSize: 14,
                  ),
                ),
              ],
            ),

            const SizedBox(height: 15),

            // View details
            SizedBox(
              width: double.infinity,
              height: 45,
              child: OutlinedButton(
                onPressed: () {
                  showAppointmentDetails(appointment);
                },
                child: const Text(
                  'View Appointment Details',
                ),
              ),
            ),
          ],
        ),
      ),
    );
  }

  // ----------------------------------------------------------
  // BUILD
  // ----------------------------------------------------------

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: const Text(
          'Doctor Appointments',
        ),
        backgroundColor:
            const Color(0xFF3F6FA8),
        foregroundColor: Colors.white,
      ),

      body: appointments.isEmpty
          ? const Center(
              child: Text(
                'No appointments available.',
                style: TextStyle(
                  fontSize: 16,
                  color: Colors.grey,
                ),
              ),
            )
          : SingleChildScrollView(
              padding: const EdgeInsets.all(20),
              child: Column(
                crossAxisAlignment:
                    CrossAxisAlignment.start,
                children: [

                  const Text(
                    'Appointments',
                    style: TextStyle(
                      fontSize: 24,
                      fontWeight: FontWeight.bold,
                    ),
                  ),

                  const SizedBox(height: 6),

                  const Text(
                    'View and manage your patient appointments.',
                    style: TextStyle(
                      fontSize: 14,
                      color: Colors.grey,
                    ),
                  ),

                  const SizedBox(height: 22),

                  ...List.generate(
                    appointments.length,
                    (index) => appointmentCard(index),
                  ),
                ],
              ),
            ),
    );
  }
}
