class DoctorConsultationDetailsScreen extends StatefulWidget {
  final Map<String, String> consultation;

  const DoctorConsultationDetailsScreen({
    super.key,
    required this.consultation,
  });

  @override
  State<DoctorConsultationDetailsScreen> createState() =>
      _DoctorConsultationDetailsScreenState();
}

class _DoctorConsultationDetailsScreenState
    extends State<DoctorConsultationDetailsScreen> {
  final TextEditingController chiefComplaintController =
      TextEditingController();

  final TextEditingController notesController =
      TextEditingController();

  final TextEditingController diagnosisController =
      TextEditingController();

  final TextEditingController adviceController =
      TextEditingController();

  DateTime? followUpDate;

  @override
  void dispose() {
    chiefComplaintController.dispose();
    notesController.dispose();
    diagnosisController.dispose();
    adviceController.dispose();
    super.dispose();
  }

  Future<void> selectFollowUpDate() async {
    final selectedDate = await showDatePicker(
      context: context,
      initialDate: DateTime.now(),
      firstDate: DateTime.now(),
      lastDate: DateTime(2035),
    );

    if (selectedDate != null) {
      setState(() {
        followUpDate = selectedDate;
      });
    }
  }

  void saveConsultation() {
    if (chiefComplaintController.text.trim().isEmpty ||
        notesController.text.trim().isEmpty ||
        diagnosisController.text.trim().isEmpty ||
        adviceController.text.trim().isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text(
            'Please complete all consultation details.',
          ),
        ),
      );
      return;
    }

    ScaffoldMessenger.of(context).showSnackBar(
      const SnackBar(
        content: Text(
          'Consultation saved successfully.',
        ),
      ),
    );

    Navigator.pop(context);
  }

  Widget consultationField({
    required String label,
    required String hint,
    required IconData icon,
    required TextEditingController controller,
    int maxLines = 3,
  }) {
    return TextField(
      controller: controller,
      maxLines: maxLines,
      decoration: InputDecoration(
        labelText: label,
        hintText: hint,
        prefixIcon: Icon(icon),
        alignLabelWithHint: true,
        filled: true,
        fillColor: Colors.white,
        border: OutlineInputBorder(
          borderRadius: BorderRadius.circular(14),
          borderSide: BorderSide.none,
        ),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    final consultation = widget.consultation;

    return Scaffold(
      backgroundColor: const Color(0xFFF7FAFC),

      appBar: AppBar(
        title: const Text('Consultation'),
        backgroundColor: const Color(0xFF3F6FA8),
        foregroundColor: Colors.white,
        elevation: 0,
      ),

      body: SingleChildScrollView(
        padding: const EdgeInsets.all(20),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            // Patient information
            Container(
              width: double.infinity,
              padding: const EdgeInsets.all(18),
              decoration: BoxDecoration(
                color: Colors.white,
                borderRadius: BorderRadius.circular(16),
                border: Border.all(
                  color: const Color(0xFFDCE5EE),
                ),
              ),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Row(
                    children: [
                      const CircleAvatar(
                        radius: 28,
                        backgroundColor: Color(0xFFEAF2FA),
                        child: Icon(
                          Icons.person_outline,
                          size: 30,
                          color: Color(0xFF3F6FA8),
                        ),
                      ),

                      const SizedBox(width: 12),

                      Expanded(
                        child: Column(
                          crossAxisAlignment:
                              CrossAxisAlignment.start,
                          children: [
                            Text(
                              consultation['patientName']!,
                              style: const TextStyle(
                                fontSize: 19,
                                fontWeight: FontWeight.bold,
                                color: Color(0xFF26384A),
                              ),
                            ),
                            const SizedBox(height: 4),
                            Text(
                              consultation['mode']!,
                              style: const TextStyle(
                                fontSize: 13,
                                color: Color(0xFF3F6FA8),
                              ),
                            ),
                          ],
                        ),
                      ),
                    ],
                  ),

                  const SizedBox(height: 16),

                  Text(
                    'Appointment: ${consultation['date']}',
                    style: const TextStyle(
                      fontSize: 13,
                      color: Colors.grey,
                    ),
                  ),

                  const SizedBox(height: 6),

                  Text(
                    'Time: ${consultation['time']}',
                    style: const TextStyle(
                      fontSize: 13,
                      color: Colors.grey,
                    ),
                  ),

                  const SizedBox(height: 6),

                  Text(
                    'Reason: ${consultation['reason']}',
                    style: const TextStyle(
                      fontSize: 13,
                      color: Color(0xFF26384A),
                    ),
                  ),
                ],
              ),
            ),

            const SizedBox(height: 24),

            const Text(
              'Consultation Details',
              style: TextStyle(
                fontSize: 19,
                fontWeight: FontWeight.bold,
                color: Color(0xFF26384A),
              ),
            ),

            const SizedBox(height: 15),

            consultationField(
              label: 'Chief Complaint',
              hint: 'Enter the patient\'s main complaint',
              icon: Icons.sick_outlined,
              controller: chiefComplaintController,
            ),

            const SizedBox(height: 14),

            consultationField(
              label: 'Consultation Notes',
              hint: 'Enter examination and consultation notes',
              icon: Icons.notes_outlined,
              controller: notesController,
            ),

            const SizedBox(height: 14),

            consultationField(
              label: 'Diagnosis',
              hint: 'Enter diagnosis',
              icon: Icons.medical_information_outlined,
              controller: diagnosisController,
            ),

            const SizedBox(height: 14),

            consultationField(
              label: 'Advice',
              hint: 'Enter medical advice and instructions',
              icon: Icons.health_and_safety_outlined,
              controller: adviceController,
            ),

            const SizedBox(height: 14),

            // Follow-up date
            InkWell(
              onTap: selectFollowUpDate,
              borderRadius: BorderRadius.circular(14),
              child: Container(
                width: double.infinity,
                padding: const EdgeInsets.all(16),
                decoration: BoxDecoration(
                  color: Colors.white,
                  borderRadius: BorderRadius.circular(14),
                  border: Border.all(
                    color: const Color(0xFFDCE5EE),
                  ),
                ),
                child: Row(
                  children: [
                    const Icon(
                      Icons.event_available_outlined,
                      color: Color(0xFF3F6FA8),
                    ),
                    const SizedBox(width: 12),
                    Expanded(
                      child: Text(
                        followUpDate == null
                            ? 'Select Follow-up Date'
                            : 'Follow-up: ${followUpDate!.day}/${followUpDate!.month}/${followUpDate!.year}',
                        style: TextStyle(
                          fontSize: 14,
                          color: followUpDate == null
                              ? Colors.grey
                              : const Color(0xFF26384A),
                        ),
                      ),
                    ),
                    const Icon(
                      Icons.calendar_month,
                      color: Colors.grey,
                    ),
                  ],
                ),
              ),
            ),

            const SizedBox(height: 28),

            // Save consultation
            SizedBox(
              width: double.infinity,
              height: 52,
              child: ElevatedButton.icon(
                onPressed: saveConsultation,
                icon: const Icon(Icons.save_outlined),
                label: const Text(
                  'Save Consultation',
                  style: TextStyle(
                    fontSize: 16,
                    fontWeight: FontWeight.bold,
                  ),
                ),
                style: ElevatedButton.styleFrom(
                  backgroundColor: const Color(0xFF3F6FA8),
                  foregroundColor: Colors.white,
                  shape: RoundedRectangleBorder(
                    borderRadius: BorderRadius.circular(14),
                  ),
                ),
              ),
            ),

            const SizedBox(height: 30),
          ],
        ),
      ),
    );
  }
}
