// ============================================================
// CREATE PRESCRIPTION SCREEN
// ============================================================

class DoctorCreatePrescriptionScreen
    extends StatefulWidget {
  const DoctorCreatePrescriptionScreen({
    super.key,
  });

  @override
  State<DoctorCreatePrescriptionScreen> createState() =>
      _DoctorCreatePrescriptionScreenState();
}

class _DoctorCreatePrescriptionScreenState
    extends State<DoctorCreatePrescriptionScreen> {
  final TextEditingController patientController =
      TextEditingController();

  final TextEditingController diagnosisController =
      TextEditingController();

  final TextEditingController medicineController =
      TextEditingController();

  final TextEditingController dosageController =
      TextEditingController();

  final TextEditingController frequencyController =
      TextEditingController();

  final TextEditingController durationController =
      TextEditingController();

  final TextEditingController instructionsController =
      TextEditingController();

  final List<Map<String, String>> medicines = [];

  bool signatureAdded = false;

  @override
  void dispose() {
    patientController.dispose();
    diagnosisController.dispose();
    medicineController.dispose();
    dosageController.dispose();
    frequencyController.dispose();
    durationController.dispose();
    instructionsController.dispose();
    super.dispose();
  }

  void addMedicine() {
    if (medicineController.text.trim().isEmpty ||
        dosageController.text.trim().isEmpty ||
        frequencyController.text.trim().isEmpty ||
        durationController.text.trim().isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text(
            'Please complete the medicine details.',
          ),
        ),
      );
      return;
    }

    setState(() {
      medicines.add({
        'medicine': medicineController.text.trim(),
        'dosage': dosageController.text.trim(),
        'frequency':
            frequencyController.text.trim(),
        'duration':
            durationController.text.trim(),
        'instructions':
            instructionsController.text.trim(),
      });

      medicineController.clear();
      dosageController.clear();
      frequencyController.clear();
      durationController.clear();
      instructionsController.clear();
    });
  }

  void removeMedicine(int index) {
    setState(() {
      medicines.removeAt(index);
    });
  }

  Future<void> addDigitalSignature() async {
    final result = await showDialog<bool>(
      context: context,
      builder: (context) {
        return AlertDialog(
          title: const Text('Digital Signature'),
          content: const Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              Icon(
                Icons.draw_outlined,
                size: 55,
                color: Color(0xFF3F6FA8),
              ),
              SizedBox(height: 15),
              Text(
                'Signature capture will allow the doctor to sign the prescription digitally.',
                textAlign: TextAlign.center,
              ),
              SizedBox(height: 12),
              Text(
                'For the current frontend POC, the signature is represented as a verified digital signature.',
                textAlign: TextAlign.center,
                style: TextStyle(
                  fontSize: 12,
                  color: Colors.grey,
                ),
              ),
            ],
          ),
          actions: [
            TextButton(
              onPressed: () {
                Navigator.pop(context, false);
              },
              child: const Text('Cancel'),
            ),
            ElevatedButton(
              onPressed: () {
                Navigator.pop(context, true);
              },
              child: const Text('Add Signature'),
            ),
          ],
        );
      },
    );

    if (result == true) {
      setState(() {
        signatureAdded = true;
      });
    }
  }

  void issuePrescription() {
    if (patientController.text.trim().isEmpty ||
        diagnosisController.text.trim().isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text(
            'Please enter patient and diagnosis details.',
          ),
        ),
      );
      return;
    }

    if (medicines.isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text(
            'Please add at least one medicine.',
          ),
        ),
      );
      return;
    }

    if (!signatureAdded) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text(
            'Please add the doctor digital signature.',
          ),
        ),
      );
      return;
    }

    showDialog(
      context: context,
      barrierDismissible: false,
      builder: (context) {
        return AlertDialog(
          title: const Text(
            'Prescription Issued',
          ),
          content: const Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              Icon(
                Icons.verified_outlined,
                size: 60,
                color: Colors.green,
              ),
              SizedBox(height: 15),
              Text(
                'The prescription has been digitally signed and issued successfully.',
                textAlign: TextAlign.center,
              ),
            ],
          ),
          actions: [
            TextButton(
              onPressed: () {
                Navigator.pop(context);
                Navigator.pop(context);
              },
              child: const Text('Done'),
            ),
          ],
        );
      },
    );
  }

  Widget inputField({
    required String label,
    required String hint,
    required IconData icon,
    required TextEditingController controller,
    TextInputType? keyboardType,
    int maxLines = 1,
  }) {
    return TextField(
      controller: controller,
      keyboardType: keyboardType,
      maxLines: maxLines,
      decoration: InputDecoration(
        labelText: label,
        hintText: hint,
        prefixIcon: Icon(icon),
        alignLabelWithHint: maxLines > 1,
        filled: true,
        fillColor: Colors.white,
        border: OutlineInputBorder(
          borderRadius:
              BorderRadius.circular(14),
          borderSide: BorderSide.none,
        ),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor:
          const Color(0xFFF7FAFC),
      appBar: AppBar(
        title: const Text(
          'Create Prescription',
        ),
        backgroundColor:
            const Color(0xFF3F6FA8),
        foregroundColor: Colors.white,
        elevation: 0,
      ),
      body: SingleChildScrollView(
        padding: const EdgeInsets.all(20),
        child: Column(
          crossAxisAlignment:
              CrossAxisAlignment.start,
          children: [

            // ==================================================
            // PATIENT DETAILS
            // ==================================================

            const Text(
              'Patient Details',
              style: TextStyle(
                fontSize: 19,
                fontWeight: FontWeight.bold,
                color: Color(0xFF26384A),
              ),
            ),

            const SizedBox(height: 15),

            inputField(
              label: 'Patient Name',
              hint: 'Enter patient name',
              icon: Icons.person_outline,
              controller: patientController,
            ),

            const SizedBox(height: 14),

            inputField(
              label: 'Diagnosis',
              hint: 'Enter diagnosis',
              icon: Icons
                  .medical_information_outlined,
              controller: diagnosisController,
            ),

            const SizedBox(height: 25),

            // ==================================================
            // MEDICINE DETAILS
            // ==================================================

            const Text(
              'Medicine Details',
              style: TextStyle(
                fontSize: 19,
                fontWeight: FontWeight.bold,
                color: Color(0xFF26384A),
              ),
            ),

            const SizedBox(height: 15),

            inputField(
              label: 'Medicine Name',
              hint: 'Example: Paracetamol',
              icon: Icons.medication_outlined,
              controller: medicineController,
            ),

            const SizedBox(height: 14),

            inputField(
              label: 'Dosage',
              hint: 'Example: 500 mg',
              icon: Icons.science_outlined,
              controller: dosageController,
            ),

            const SizedBox(height: 14),

            inputField(
              label: 'Frequency',
              hint: 'Example: Twice daily',
              icon: Icons.schedule_outlined,
              controller: frequencyController,
            ),

            const SizedBox(height: 14),

            inputField(
              label: 'Duration',
              hint: 'Example: 3 days',
              icon: Icons.timer_outlined,
              controller: durationController,
            ),

            const SizedBox(height: 14),

            inputField(
              label: 'Instructions',
              hint:
                  'Example: Take after food',
              icon: Icons.notes_outlined,
              controller: instructionsController,
              maxLines: 2,
            ),

            const SizedBox(height: 15),

            SizedBox(
              width: double.infinity,
              height: 46,
              child: OutlinedButton.icon(
                onPressed: addMedicine,
                icon: const Icon(Icons.add),
                label: const Text(
                  'Add Medicine',
                  style: TextStyle(
                    fontWeight: FontWeight.bold,
                  ),
                ),
              ),
            ),

            const SizedBox(height: 18),

            // ==================================================
            // ADDED MEDICINES
            // ==================================================

            if (medicines.isNotEmpty) ...[
              const Text(
                'Added Medicines',
                style: TextStyle(
                  fontSize: 16,
                  fontWeight: FontWeight.bold,
                  color: Color(0xFF26384A),
                ),
              ),
              const SizedBox(height: 10),

              ...List.generate(
                medicines.length,
                (index) {
                  final medicine =
                      medicines[index];

                  return Card(
                    margin:
                        const EdgeInsets.only(
                      bottom: 10,
                    ),
                    elevation: 1,
                    child: Padding(
                      padding:
                          const EdgeInsets.all(14),
                      child: Row(
                        crossAxisAlignment:
                            CrossAxisAlignment
                                .start,
                        children: [
                          const Icon(
                            Icons
                                .medication_outlined,
                            color:
                                Color(0xFF3F6FA8),
                          ),
                          const SizedBox(width: 10),
                          Expanded(
                            child: Column(
                              crossAxisAlignment:
                                  CrossAxisAlignment
                                      .start,
                              children: [
                                Text(
                                  medicine[
                                      'medicine']!,
                                  style:
                                      const TextStyle(
                                    fontSize: 15,
                                    fontWeight:
                                        FontWeight
                                            .bold,
                                  ),
                                ),
                                const SizedBox(
                                    height: 5),
                                Text(
                                  '${medicine['dosage']} • ${medicine['frequency']} • ${medicine['duration']}',
                                  style:
                                      const TextStyle(
                                    fontSize: 12,
                                    color:
                                        Colors.grey,
                                  ),
                                ),
                                if (medicine[
                                        'instructions']!
                                    .isNotEmpty) ...[
                                  const SizedBox(
                                      height: 5),
                                  Text(
                                    medicine[
                                        'instructions']!,
                                    style:
                                        const TextStyle(
                                      fontSize: 12,
                                    ),
                                  ),
                                ],
                              ],
                            ),
                          ),
                          IconButton(
                            onPressed: () {
                              removeMedicine(
                                index,
                              );
                            },
                            icon: const Icon(
                              Icons
                                  .delete_outline,
                              color: Colors.red,
                            ),
                          ),
                        ],
                      ),
                    ),
                  );
                },
              ),

              const SizedBox(height: 15),
            ],

            // ==================================================
            // DIGITAL SIGNATURE
            // ==================================================

            const Text(
              'Digital Signature',
              style: TextStyle(
                fontSize: 19,
                fontWeight: FontWeight.bold,
                color: Color(0xFF26384A),
              ),
            ),

            const SizedBox(height: 15),

            Container(
              width: double.infinity,
              padding:
                  const EdgeInsets.all(18),
              decoration: BoxDecoration(
                color: Colors.white,
                borderRadius:
                    BorderRadius.circular(16),
                border: Border.all(
                  color:
                      const Color(0xFFDCE5EE),
                ),
              ),
              child: Column(
                children: [
                  Icon(
                    signatureAdded
                        ? Icons
                            .verified_outlined
                        : Icons
                            .draw_outlined,
                    size: 45,
                    color: signatureAdded
                        ? Colors.green
                        : const Color(
                            0xFF3F6FA8),
                  ),
                  const SizedBox(height: 10),
                  Text(
                    signatureAdded
                        ? 'Doctor Signature Added'
                        : 'Doctor Signature Required',
                    style: TextStyle(
                      fontSize: 15,
                      fontWeight:
                          FontWeight.bold,
                      color: signatureAdded
                          ? Colors.green
                          : const Color(
                              0xFF26384A),
                    ),
                  ),
                  const SizedBox(height: 6),
                  Text(
                    signatureAdded
                        ? 'Prescription is ready to be digitally signed and issued.'
                        : 'Add your digital signature before issuing the prescription.',
                    textAlign:
                        TextAlign.center,
                    style: const TextStyle(
                      fontSize: 12,
                      color: Colors.grey,
                    ),
                  ),
                  const SizedBox(height: 14),
                  SizedBox(
                    width: double.infinity,
                    height: 45,
                    child: OutlinedButton.icon(
                      onPressed:
                          addDigitalSignature,
                      icon: Icon(
                        signatureAdded
                            ? Icons.edit_outlined
                            : Icons.draw_outlined,
                      ),
                      label: Text(
                        signatureAdded
                            ? 'Change Signature'
                            : 'Add Digital Signature',
                      ),
                    ),
                  ),
                ],
              ),
            ),

            const SizedBox(height: 28),

            // ==================================================
            // ISSUE PRESCRIPTION
            // ==================================================

            SizedBox(
              width: double.infinity,
              height: 52,
              child: ElevatedButton.icon(
                onPressed:
                    issuePrescription,
                icon: const Icon(
                  Icons.verified_outlined,
                ),
                label: const Text(
                  'Sign & Issue Prescription',
                  style: TextStyle(
                    fontSize: 16,
                    fontWeight:
                        FontWeight.bold,
                  ),
                ),
                style:
                    ElevatedButton.styleFrom(
                  backgroundColor:
                      const Color(0xFF3F6FA8),
                  foregroundColor:
                      Colors.white,
                  shape:
                      RoundedRectangleBorder(
                    borderRadius:
                        BorderRadius.circular(
                            14),
                  ),
                ),
              ),
            ),

            const SizedBox(height: 30),
          ],
        ),
      ),
    );
  }
}


