                fontWeight: FontWeight.w600,
                color: Color(0xFF26384A),
              ),
            ),
          ),
        ],
      ),
    );
  }
}
// ============================================================
// HOSPITAL REGISTRATION SCREEN
// ============================================================

class HospitalRegistrationScreen extends StatefulWidget {
  const HospitalRegistrationScreen({super.key});

  @override
  State<HospitalRegistrationScreen> createState() =>
      _HospitalRegistrationScreenState();
}

class _HospitalRegistrationScreenState
    extends State<HospitalRegistrationScreen> {
  final hospitalNameController = TextEditingController();
  final contactPersonController = TextEditingController();
  final addressController = TextEditingController();
  final phoneController = TextEditingController();
  final otpController = TextEditingController();

  bool otpSent = false;
  bool otpVerified = false;

  @override
  void dispose() {
    hospitalNameController.dispose();
    contactPersonController.dispose();
    addressController.dispose();
    phoneController.dispose();
    otpController.dispose();
    super.dispose();
  }

  void sendOTP() {
    if (phoneController.text.length != 10) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('Please enter a valid 10-digit phone number.'),
        ),
      );
      return;
    }

    setState(() {
      otpSent = true;
    });

    ScaffoldMessenger.of(context).showSnackBar(
      const SnackBar(
        content: Text('OTP sent! Test OTP: 123456'),
      ),
    );
  }

  void verifyOTP() {
    if (otpController.text == '123456') {
      setState(() {
        otpVerified = true;
      });

      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('Phone number verified successfully.'),
        ),
      );
    } else {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('Invalid OTP. Please enter 123456.'),
        ),
      );
    }
  }

  Future<void> registerHospital() async {
    if (hospitalNameController.text.trim().isEmpty ||
        contactPersonController.text.trim().isEmpty ||
        addressController.text.trim().isEmpty ||
        phoneController.text.length != 10) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('Please fill in all required fields.'),
        ),
      );
      return;
    }

    if (!otpVerified) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('Please verify your phone number first.'),
        ),
      );
      return;
    }

    final prefs = await SharedPreferences.getInstance();

    await prefs.setBool('hospitalRegistered', true);

    if (!mounted) return;

    Navigator.pushReplacement(
      context,
      MaterialPageRoute(
        builder: (context) => const HospitalRegistrationSuccessScreen(),
      ),
    );
  }

  Widget inputField({
    required TextEditingController controller,
    required String label,
    required IconData icon,
    TextInputType keyboardType = TextInputType.text,
    int? maxLength,
  }) {
    return TextField(
      controller: controller,
      keyboardType: keyboardType,
      maxLength: maxLength,
      decoration: InputDecoration(
        labelText: label,
        prefixIcon: Icon(icon),
        border: OutlineInputBorder(
          borderRadius: BorderRadius.circular(12),
        ),
        filled: true,
        fillColor: Colors.grey.shade50,
        counterText: '',
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        backgroundColor: Colors.green,
        foregroundColor: Colors.white,
        title: const Text(
          'Hospital Registration',
          style: TextStyle(
            fontWeight: FontWeight.bold,
          ),
        ),
        centerTitle: true,
      ),

      body: SingleChildScrollView(
        padding: const EdgeInsets.all(20),
        child: Column(
          children: [
            const Icon(
              Icons.local_hospital,
              size: 70,
              color: Colors.green,
            ),

            const SizedBox(height: 12),

            const Text(
              'Register Your Hospital',
              style: TextStyle(
                fontSize: 24,
                fontWeight: FontWeight.bold,
              ),
            ),

            const SizedBox(height: 8),

            const Text(
              'Register your hospital to receive and respond to emergency requests.',
              textAlign: TextAlign.center,
              style: TextStyle(
                color: Colors.grey,
                fontSize: 14,
              ),
            ),

            const SizedBox(height: 25),

            inputField(
              controller: hospitalNameController,
              label: 'Hospital Name',
              icon: Icons.local_hospital,
            ),

            const SizedBox(height: 15),

            inputField(
              controller: contactPersonController,
              label: 'Administrator / Contact Person',
              icon: Icons.person,
            ),

            const SizedBox(height: 15),

            inputField(
              controller: addressController,
              label: 'Hospital Address',
              icon: Icons.location_on,
            ),

            const SizedBox(height: 15),

            TextField(
              controller: phoneController,
              keyboardType: TextInputType.phone,
              maxLength: 10,
              decoration: InputDecoration(
                labelText: 'Hospital Phone Number',
                prefixText: '+91 ',
                prefixIcon: const Icon(Icons.phone),
                border: OutlineInputBorder(
                  borderRadius: BorderRadius.circular(12),
                ),
                filled: true,
                fillColor: Colors.grey.shade50,
                counterText: '',
              ),
            ),

            const SizedBox(height: 15),

            if (!otpSent)
              SizedBox(
                width: double.infinity,
                child: ElevatedButton.icon(
                  onPressed: sendOTP,
                  icon: const Icon(Icons.sms),
                  label: const Text('Send OTP'),
                ),
              ),

            if (otpSent) ...[
              TextField(
                controller: otpController,
                keyboardType: TextInputType.number,
                maxLength: 6,
                decoration: InputDecoration(
                  labelText: 'Enter OTP',
                  prefixIcon: const Icon(Icons.lock),
                  border: OutlineInputBorder(
                    borderRadius: BorderRadius.circular(12),
                  ),
                  filled: true,
                  fillColor: Colors.grey.shade50,
                  counterText: '',
                ),
              ),

              const SizedBox(height: 10),

              SizedBox(
                width: double.infinity,
                child: ElevatedButton(
                  onPressed: otpVerified ? null : verifyOTP,
                  child: Text(
                    otpVerified ? 'Phone Verified ✓' : 'Verify OTP',
                  ),
                ),
              ),
            ],

            const SizedBox(height: 25),

            SizedBox(
              width: double.infinity,
              height: 52,
              child: ElevatedButton.icon(
                onPressed: registerHospital,
                icon: const Icon(Icons.app_registration),
                label: const Text(
                  'Register Hospital',
                  style: TextStyle(
                    fontSize: 17,
                    fontWeight: FontWeight.bold,
                  ),
                ),
                style: ElevatedButton.styleFrom(
                  backgroundColor: Colors.green,
                  foregroundColor: Colors.white,
                  shape: RoundedRectangleBorder(
                    borderRadius: BorderRadius.circular(12),
                  ),
                ),
              ),
            ),

            const SizedBox(height: 20),

            const Text(
              'Emergency services can be managed through the Hospital Portal.',
              textAlign: TextAlign.center,
              style: TextStyle(
                fontSize: 12,
                color: Colors.grey,
              ),
            ),
          ],
        ),
      ),
    );
  }
}


